    // Transition to B occurs from State A (y[0]) when input w is 1.
    assign Y1 = y[0] & w;

    // Y3 is the next state logic for state bit 3 (State D: 001000)
    // Transitions to D occur from State B (y[1]), C (y[2]), E (y[4]), or F (y[5]) when input w is 0.
    assign Y3 = (y[1] | y[2] | y[4] | y[5]) & ~w;

endmodule

