module top_module (
    input clk,
    input resetn,
    input [3:1] r,
    output [3:1] g
);

    // State Encoding: 2 bits for 4 states (A, B, C, D)
    localparam [1:0] STATE_A = 2'b00;
    localparam [1:0] STATE_B = 2'b01;
    localparam [1:0] STATE_C = 2'b10;
    localparam [1:0] STATE_D = 2'b11;

    // State Registers
    reg [1:0] current_state;
    reg [1:0] next_state;

    // State Flip-Flops (Synchronous Reset)
    // Resets to STATE_A when resetn is low
    always @(posedge clk) begin
        if (!resetn) begin
            current_state <= STATE_A;
        end else begin
            current_state <= next_state;
        end
    end

    // Next State Logic (State Table)
    // Implements the priority arbiter logic described
    always @(*) begin
        case (current_state)
            STATE_A: begin
                // Priority: Device 1 > Device 2 > Device 3
                // If r[1] is high, grant to Device 1 (State B)
                if (r[1]) begin
                    next_state = STATE_B;
                end 
                // Else if r[2] is high, grant to Device 2 (State C)
                else if (r[2]) begin
                    next_state = STATE_C;
                end 
                // Else if r[3] is high, grant to Device 3 (State D)
                // Note: Prompt comment had a typo (r3=0), functional text implies r3=1
                else if (r[3]) begin
                    next_state = STATE_D;
                end 
                // Else stay in idle state A
                else begin
                    next_state = STATE_A;
                end
            end
            STATE_B: begin
                // Stay in B (grant Device 1) as long as r[1] is high
                if (r[1]) begin
                    next_state = STATE_B;
                end else begin
                    next_state = STATE_A;
                end
            end
            STATE_C: begin
                // Stay in C (grant Device 2) as long as r[2] is high
                if (r[2]) begin
                    next_state = STATE_C;
                end else begin
                    next_state = STATE_A;
                end
            end
            STATE_D: begin
                // Stay in D (grant Device 3) as long as r[3] is high
                if (r[3]) begin
                    next_state = STATE_D;
                end else begin
                    next_state = STATE_A;
                end
            end
            default: next_state = STATE_A;
        endcase
    end

    // Output Logic
    // g[i] is asserted high only in the corresponding state
    assign g[1] = (current_state == STATE_B);
    assign g[2] = (current_state == STATE_C);
    assign g[3] = (current_state == STATE_D);

endmodule

