module top_module (
	input clk,
	input resetn,
	input x,
	input y,
	output f,
	output g
);

	// State encoding
	localparam STATE_A = 3'd0;
	localparam STATE_F1 = 3'd1;
	localparam STATE_X1 = 3'd2;
	localparam STATE_X10 = 3'd3;
	localparam STATE_G1 = 3'd4;
	localparam STATE_G2 = 3'd5;
	localparam STATE_G_PERM = 3'd6;
	localparam STATE_G_ZERO = 3'd7;

	// State register
	reg [2:0] current_state, next_state;

	// Sequential logic: state register with synchronous reset
	always @(posedge clk) begin
		if (!resetn)
			current_state <= STATE_A;
		else
			current_state <= next_state;
	end

	// Combinational logic: next state and outputs
	always @(*) begin
		// Default outputs
		f = 0;
		g = 0;
		next_state = current_state;

		case (current_state)
			STATE_A: begin
				if (resetn)
					next_state = STATE_F1;
				else
					next_state = STATE_A;
			end

			STATE_F1: begin
				f = 1;
				next_state = STATE_X1;
			end

			STATE_X1: begin
				if (x)
					next_state = STATE_X1;
				else
					next_state = STATE_X10;
			end

			STATE_X10: begin
				if (x)
					next_state = STATE_G1;
				else
					next_state = STATE_X1;
			end

			STATE_G1: begin
				g = 1;
				if (y)
					next_state = STATE_G_PERM;
				else
					next_state = STATE_G2;
			end

			STATE_G2: begin
				g = 1;
				if (y)
					next_state = STATE_G_PERM;
				else
					next_state = STATE_G_ZERO;
			end

			STATE_G_PERM: begin
				g = 1;
				if (!resetn)
					next_state = STATE_A;
				else
					next_state = STATE_G_PERM;
			end

			STATE_G_ZERO: begin
				if (!resetn)
					next_state = STATE_A;
				else
					next_state = STATE_G_ZERO;
			end

			default: begin
				next_state = STATE_A;
			end
		endcase
	end

