module top_module (
    input clk,
    input resetn,
    input x,
    input y,
    output f,
    output g
);

    // State encoding
    localparam STATE_A = 3'b000;  // Initial/reset state
    localparam STATE_B = 3'b001;  // f=1 for one cycle after reset de-asserted
    localparam STATE_C = 3'b010;  // Looking for x=1
    localparam STATE_D = 3'b011;  // Saw x=1, looking for x=0
    localparam STATE_E = 3'b100;  // Saw x=1,0, looking for x=1
    localparam STATE_F = 3'b101;  // Detected 1,0,1, g=1, waiting for y (cycle 1)
    localparam STATE_G = 3'b110;  // g=1, waiting for y (cycle 2)
    localparam STATE_H = 3'b111;  // y not found, g=0 permanently

    reg [2:0] state, next_state;

    // State register (synchronous reset)
    always @(posedge clk) begin
        if (!resetn)
            state <= STATE_A;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            STATE_A: begin
                if (!resetn)
                    next_state = STATE_A;
                else
                    next_state = STATE_B;
            end
            STATE_B: next_state = STATE_C;
            STATE_C: begin
                if (x)
                    next_state = STATE_D;
                else
                    next_state = STATE_C;
            end
            STATE_D: begin
                if (!x)
                    next_state = STATE_E;
                else
                    next_state = STATE_C;
            end
            STATE_E: begin
                if (x)
                    next_state = STATE_F;
                else
                    next_state = STATE_C;
            end
            STATE_F: begin
                if (y)
                    next_state = STATE_G;  // y found, keep g=1
                else
                    next_state = STATE_G;  // Continue to next cycle to check y again
            end
            STATE_G: begin
                if (y)
                    next_state = STATE_G;  // y found, keep g=1 permanently
                else
                    next_state = STATE_H;  // y not found within 2 cycles, set g=0
            end
            STATE_H: next_state = STATE_H;  // g=0 permanently until reset
            default: next_state = STATE_A;
        endcase
    end

    // Output logic
    assign f = (state == STATE_B);
    assign g = (state == STATE_F || state == STATE_G);

endmodule

module top_module (
	input clk,
	input resetn,
	input x,
	input y,
	output f,
	output g
);

	// State encoding
	localparam [2:0] STATE_A    = 3'b000;
	localparam [2:0] STATE_F    = 3'b001;
	localparam [2:0] STATE_X0   = 3'b010;
	localparam [2:0] STATE_X1   = 3'b011;
	localparam [2:0] STATE_X2   = 3'b100;
	localparam [2:0] STATE_G1   = 3'b101;
	localparam [2:0] STATE_G2   = 3'b110;
	localparam [2:0] STATE_G_PERM = 3'b111;

	reg [2:0] state, next_state;
	reg f_next, g_next;

	// State register with synchronous reset
	always @(posedge clk) begin
		if (!resetn)
			state <= STATE_A;
		else
			state <= next_state;
	end

	// Next state logic
	always @(*) begin
		case (state)
			STATE_A: begin
				if (!resetn)
					next_state = STATE_A;
				else
					next_state = STATE_F;
			end
			STATE_F: begin
				next_state = STATE_X0;
			end
			STATE_X0: begin
				if (x)
					next_state = STATE_X1;
				else
					next_state = STATE_X0;
			end
			STATE_X1: begin
				if (x)
					next_state = STATE_X1;
				else
					next_state = STATE_X2;
			end
			STATE_X2: begin
				if (x)
					next_state = STATE_G1;
				else
					next_state = STATE_X0;
			end
			STATE_G1: begin
				if (y)
					next_state = STATE_G_PERM;
				else
					next_state = STATE_G2;
			end
			STATE_G2: begin
				if (y)
					next_state = STATE_G_PERM;
				else
					next_state = STATE_G_ZERO;
			end
			STATE_G_PERM: begin
				next_state = STATE_G_PERM;
			end
			STATE_G_ZERO: begin
				next_state = STATE_G_ZERO;
			end
			default: begin
				next_state = STATE_A;
			end
		endcase
	end

	// Output logic
	always @(*) begin
		case (state)
			STATE_A: begin
				f_next = 0;
				g_next = 0;
			end
			STATE_F: begin
				f_next = 1;
				g_next = 0;
			end
			STATE_X0, STATE_X1, STATE_X2: begin
				f_next = 0;
				g_next = 0;
			end
			STATE_G1, STATE_G2, STATE_G_PERM: begin
				f_next = 0;
				g_next = 1;
			end
			STATE_G_ZERO: begin
				f_next = 0;
				g_next = 0;
			end
			default: begin
				f_next = 0;
				g_next = 0;
			end
		endcase
	end

	// Output registers
	always @(posedge clk) begin
		f <= f_next;
		g <= g_next;
	end

endmodule

module top_module (
	input clk,
	input resetn,
	input x,
	input y,
	output f,
	output g
);

// State encoding
localparam [3:0] S_A = 4'b0000;  // Reset state
localparam [3:0] S_B = 4'b0001;  // f=1 for one cycle after reset
localparam [3:0] S_C = 4'b0010;  // Monitor x for first 1
localparam [3:0] S_D = 4'b0011;  // x=1, monitor for 0
localparam [3:0] S_E = 4'b0100;  // x=1,0, monitor for 1
localparam [3:0] S_F = 4'b0101;  // g=1, y monitoring cycle 0
localparam [3:0] S_G = 4'b0110;  // g=1, y monitoring cycle 1
localparam [3:0] S_H = 4'b0111;  // g=1 permanent
localparam [3:0] S_I = 4'b1000;  // g=0 permanent

reg [3:0] state, next_state;

// State register (synchronous with resetn)
always @(posedge clk) begin
	if (!resetn)
		state <= S_A;
	else
		state <= next_state;
end

// Next state logic
always @(*) begin
	case (state)
		S_A: begin
			if (!resetn)
				next_state = S_A;
			else
				next_state = S_B;
		end
		S_B: next_state = S_C;
		S_C: begin
			if (x == 1)
				next_state = S_D;
			else
				next_state = S_C;
		end
		S_D: begin
			if (x == 0)
				next_state = S_E;
			else
				next_state = S_D;
		end
		S_E: begin
			if (x == 1)
				next_state = S_F;
			else
				next_state = S_C;
		end
		S_F: begin
			if (y == 1)
				next_state = S_H;
			else
				next_state = S_G;
		end
		S_G: begin
			if (y == 1)
				next_state = S_H;
			else
				next_state = S_I;
		end
		S_H: next_state = S_H;
		S_I: next_state = S_I;
		default: next_state = S_A;
	endcase
end

// Output logic
assign f = (state == S_B);
assign g = (state == S_F || state == S_G || state == S_H);

endmodule

module top_module (
	input clk,
	input x,
	input [2:0] y,
	output reg Y0,
	output reg z
);

    always @(*) begin
        // Logic for Y0 (Next State Bit 0)
        // Based on the state-assigned table:
        // State 000 (y[2]=0, y[0]=0): Y0 = x
        // State 001 (y[2]=0, y[0]=1): Y0 = ~x
        // State 010 (y[2]=0, y[0]=0): Y0 = x
        // State 011 (y[2]=0, y[0]=1): Y0 = ~x
        // State 100 (y[2]=1):         Y0 = ~x
        //
        // Simplification:
        // If y[2] is 1, Y0 = ~x
        // If y[2] is 0, Y0 = x ^ y[0]
        Y0 = y[2] ? ~x : (x ^ y[0]);

