module top_module (
    input clk,
    input reset,
    input s,
    input w,
    output reg z
);

    // States: [2:0] = [cycle_count(0-2), ones_count(0-3)]
    // But we encode as: state = cycle_count * 4 + ones_count
    localparam [3:0] STATE_A = 4'd0;
    localparam [3:0] STATE_0_0 = 4'd0; // cycle 0, ones 0
    localparam [3:0] STATE_0_1 = 4'd1; // cycle 0, ones 1
    localparam [3:0] STATE_1_0 = 4'd4; // cycle 1, ones 0
    localparam [3:0] STATE_1_1 = 4'd5; // cycle 1, ones 1
    localparam [3:0] STATE_1_2 = 4'd6; // cycle 1, ones 2
    localparam [3:0] STATE_2_0 = 4'd8; // cycle 2, ones 0
    localparam [3:0] STATE_2_1 = 4'd9; // cycle 2, ones 1
    localparam [3:0] STATE_2_2 = 4'd10; // cycle 2, ones 2
    localparam [3:0] STATE_2_3 = 4'd11; // cycle 2, ones 3

    reg [3:0] state, next_state;

    // State register (synchronous reset)
    always @(posedge clk) begin
        if (reset)
            state <= STATE_A;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            STATE_A: begin
                if (s)
                    next_state = STATE_0_0;
                else
                    next_state = STATE_A;
            end
            STATE_0_0: next_state = (w) ? STATE_1_1 : STATE_1_0;
            STATE_0_1: next_state = (w) ? STATE_1_2 : STATE_1_1;
            STATE_1_0: next_state = (w) ? STATE_2_1 : STATE_2_0;
            STATE_1_1: next_state = (w) ? STATE_2_2 : STATE_2_1;
            STATE_1_2: next_state = (w) ? STATE_2_3 : STATE_2_2;
            STATE_2_0: next_state = STATE_0_1;
            STATE_2_1: next_state = STATE_0_2;
            STATE_2_2: next_state = STATE_0_3;
            STATE_2_3: next_state = STATE_0_4;
            default: next_state = STATE_A;
        endcase
    end

    // Corrected state encoding for 3-cycle window tracking
    localparam [3:0] S_A = 4'd0;
    localparam [3:0] S_0_0 = 4'd1;  // cycle 0, count 0
    localparam [3:0] S_0_1 = 4'd2;  // cycle 0, count 1
    localparam [3:0] S_1_0 = 4'd3;  // cycle 1, count 0
    localparam [3:0] S_1_1 = 4'd4;  // cycle 1, count 1
    localparam [3:0] S_1_2 = 4'd5;  // cycle 1, count 2
    localparam [3:0] S_2_0 = 4'd6;  // cycle 2, count 0
    localparam [3:0] S_2_1 = 4'd7;  // cycle 2, count 1
    localparam [3:0] S_2_2 = 4'd8;  // cycle 2, count 2
    localparam [3:0] S_2_3 = 4'd9;  // cycle 2, count 3

    always @(posedge clk) begin
        if (reset)
            state <= S_A;
        else
            state <= next_state;
    end

    always @(*) begin
        case (state)
            S_A: begin
                if (s)
                    next_state = S_0_0;
                else
                    next_state = S_A;
            end
            S_0_0: next_state = (w) ? S_1_1 : S_1_0;
            S_0_1: next_state = (w) ? S_1_2 : S_1_1;
            S_1_0: next_state = (w) ? S_2_1 : S_2_0;
            S_1_1: next_state = (w) ? S_2_2 : S_2_1;
            S_1_2: next_state = (w) ? S_2_3 : S_2_2;
            S_2_0: next_state = S_0_1;
            S_2_1: next_state = S_0_2;
            S_2_2: next_state = S_0_3;
            S_2_3: next_state = S_0_4;
            default: next_state = S_A;
        endcase
    end

    // Output logic: z = 1 when next state is from S_2_2 (exactly 2 ones in 3 cycles)
    always @(posedge clk) begin
        if (reset)
            z <= 1'b0;
        else
            z <= (state == S_2_2) ? 1'b1 : 1'b0;
    end

endmodule

module top_module (
    input clk,
    input reset,
    input s,
    input w,
    output reg z
);

    parameter [3:0] A = 4'd0;
    parameter [3:0] C0_0 = 4'd1;
    parameter [3:0] C1_0 = 4'd2;
    parameter [3:0] C1_1 = 4'd3;
    parameter [3:0] C2_0 = 4'd4;
    parameter [3:0] C2_1 = 4'd5;
    parameter [3:0] C2_2 = 4'd6;
    parameter [3:0] OUT_0 = 4'd7;
    parameter [3:0] OUT_1 = 4'd8;

    reg [3:0] state, next_state;

    // State register
    always @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            A: begin
                if (s)
                    next_state = C0_0;
                else
                    next_state = A;
            end
            C0_0: begin
                if (w)
                    next_state = C1_1;
                else
                    next_state = C1_0;
            end
            C1_0: begin
                if (w)
                    next_state = C2_1;
                else
                    next_state = C2_0;
            end
            C1_1: begin
                if (w)
                    next_state = C2_2;
                else
                    next_state = C2_1;
            end
            C2_0: begin
                next_state = OUT_0;
            end
            C2_1: begin
                if (w)
                    next_state = OUT_1;
                else
                    next_state = OUT_0;
            end
            C2_2: begin
                if (w)
                    next_state = OUT_0;
                else
                    next_state = OUT_1;
            end
            OUT_0: begin
                next_state = C0_0;
            end
            OUT_1: begin
                next_state = C0_0;
            end
            default: next_state = A;
        endcase
    end

    // Output logic
    always @(*) begin
        case (state)
            A: z = 0;
            C0_0: z = 0;
            C1_0: z = 0;
            C1_1: z = 0;
            C2_0: z = 0;
            C2_1: z = 0;
            C2_2: z = 0;
