module top_module(
	input clk,
	input load,
	input [255:0] data,
	output reg [255:0] q);

    integer i, x, y, dx, dy, nx, ny, neighbor_count;
    reg [255:0] next_q;

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            for (i = 0; i < 256; i = i + 1) begin
                y = i >> 4;
                x = i & 15;
                neighbor_count = 0;

                for (dy = -1; dy <= 1; dy = dy + 1) begin
                    for (dx = -1; dx <= 1; dx = dx + 1) begin
                        if (dx == 0 && dy == 0) continue;

                        // Wrap around logic for toroidal grid
                        // Adding 16 ensures the result is positive before modulo
                        nx = (x + dx + 16) % 16;
                        ny = (y + dy + 16) % 16;

                        // Calculate neighbor index: row * 16 + col
                        neighbor_count = neighbor_count + q[ny * 16 + nx];
                    end
                end

                // Apply Game of Life rules
                if (neighbor_count == 3)
                    next_q[i] = 1'b1;
                else if (neighbor_count == 2)
                    next_q[i] = q[i];
                else
                    next_q[i] = 1'b0;
            end
            q <= next_q;
        end
    end

endmodule

module top_module(
	input clk,
	input load,
	input [255:0] data,
	output reg [255:0] q
);

    reg [255:0] next_q;
    integer r, c, i;
    integer count;
    integer nr, nc;

    // Combinational logic to calculate the next state of the grid
    always @(*) begin
        next_q = 0;
        for (r = 0; r < 16; r = r + 1) begin
            for (c = 0; c < 16; c = c + 1) begin
                i = r * 16 + c;
                count = 0;

                // Top-Left neighbor
                nr = (r == 0) ? 15 : r - 1;
                nc = (c == 0) ? 15 : c - 1;
                count = count + q[nr * 16 + nc];

                // Top neighbor
                nr = (r == 0) ? 15 : r - 1;
                nc = c;
                count = count + q[nr * 16 + nc];

                // Top-Right neighbor
                nr = (r == 0) ? 15 : r - 1;
                nc = (c == 15) ? 0 : c + 1;
                count = count + q[nr * 16 + nc];

                // Left neighbor
                nr = r;
                nc = (c == 0) ? 15 : c - 1;
                count = count + q[nr * 16 + nc];

                // Right neighbor
                nr = r;
                nc = (c == 15) ? 0 : c + 1;
                count = count + q[nr * 16 + nc];

                // Bottom-Left neighbor
                nr = (r == 15) ? 0 : r + 1;
                nc = (c == 0) ? 15 : c - 1;
                count = count + q[nr * 16 + nc];

                // Bottom neighbor
                nr = (r == 15) ? 0 : r + 1;
                nc = c;
                count = count + q[nr * 16 + nc];

                // Bottom-Right neighbor
                nr = (r == 15) ? 0 : r + 1;
                nc = (c == 15) ? 0 : c + 1;
                count = count + q[nr * 16 + nc];

                // Apply Game of Life Rules
                // (1) 0-1 neighbour: Cell becomes 0.
                // (2) 2 neighbours: Cell state does not change.
                // (3) 3 neighbours: Cell becomes 1.
                // (4) 4+ neighbours: Cell becomes 0.
                if (count == 3)
                    next_q[i] = 1'b1;
                else if (count == 2)
                    next_q[i] = q[i];
                else
                    next_q[i] = 1'b0;
            end
        end
    end

    // Sequential logic to update the state on clock edge
    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

endmodule

module top_module(
	input clk,
	input load,
	input [255:0] data,
	output reg [255:0] q);

    // Combinational logic to compute the next state of the grid
    wire [255:0] next_q;
    genvar i, j;

    generate
        // Iterate over each row (0-15)
        for(i=0; i<16; i=i+1) begin : row_gen
            // Iterate over each column (0-15)
            for(j=0; j<16; j=j+1) begin : col_gen
                // Calculate neighbor row indices with toroidal wrapping
                wire [3:0] r_prev = (i == 0) ? 4'd15 : i - 1;
                wire [3:0] r_curr = i;
                wire [3:0] r_next = (i == 15) ? 4'd0 : i + 1;

                // Calculate neighbor column indices with toroidal wrapping
                wire [3:0] c_prev = (j == 0) ? 4'd15 : j - 1;
                wire [3:0] c_curr = j;
                wire [3:0] c_next = (j == 15) ? 4'd0 : j + 1;

                // Sum the 8 neighbors
                // q is indexed as q[row*16 + col], which is {row, col}
                wire [3:0] neighbors;
                assign neighbors = 
                    q[{r_prev, c_prev}] + q[{r_prev, c_curr}] + q[{r_prev, c_next}] +
                    q[{r_curr, c_prev}] +                       q[{r_curr, c_next}] +
                    q[{r_next, c_prev}] + q[{r_next, c_curr}] + q[{r_next, c_next}];

                // Determine next state based on Game of Life rules
                wire next_bit;
                assign next_bit = (neighbors == 3) ? 1'b1 : 
                                  ((neighbors == 2) ? q[{r_curr, c_curr}] : 1'b0);

                // Assign the computed bit to the next state vector
                assign next_q[{i, j}] = next_bit;
            end
        end
    endgenerate

    // Sequential logic to update the state register
    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

endmodule

