    integer i, r, c, nr, nc, n, r_idx, c_idx, bit_idx;

    // Combinational logic to compute the next state of the grid
    always @(*) begin
        next_q = 0; // Initialize to avoid latches (though loop covers all bits)

        for (i = 0; i < 256; i = i + 1) begin
            r = i >> 4;       // Row index (0-15)
            c = i & 15;       // Col index (0-15)
            n = 0;            // Neighbor count

            // Iterate over 3x3 neighborhood
            for (nr = r - 1; nr <= r + 1; nr = nr + 1) begin
                for (nc = c - 1; nc <= c + 1; nc = nc + 1) begin
                    // Skip the cell itself
                    if (nr == r && nc == c) continue;

                    // Handle toroidal wrapping (modulo 16)
                    // Using bitwise AND for efficiency since 16 is power of 2
                    // nr & 15 handles wrapping for range -1 to 16 correctly in 2's complement
                    r_idx = nr & 15;
                    c_idx = nc & 15;

                    bit_idx = (r_idx << 4) | c_idx;

                    // Count alive neighbors
                    n = n + q[bit_idx];
                end
            end

            // Apply Game of Life rules
            if (n == 3)
                next_q[i] = 1;
            else if (n == 2)
                next_q[i] = q[i];
            else
                next_q[i] = 0;
        end
    end

    // Sequential logic to update the grid state on clock edge
    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

endmodule

module top_module(
    input clk,
    input reset,
    input ena,
    output reg pm,
    output reg [7:0] hh,
    output reg [7:0] mm,
    output reg [7:0] ss);

    always @(posedge clk) begin
        if (reset) begin
            ss <= 8'h00;
            mm <= 8'h00;
            hh <= 8'h12;
            pm <= 1'b0;
        end
        else if (ena) begin
            // Seconds Logic
            if (ss == 8'h59) begin
                ss <= 8'h00;
                // Minutes Logic
                if (mm == 8'h59) begin
                    mm <= 8'h00;
                    // Hours Logic
                    if (hh == 8'h12) begin
                        hh <= 8'h01;
                        // pm remains unchanged (12 -> 01 does not toggle AM/PM)
                    end
                    else if (hh == 8'h11) begin
                        hh <= 8'h12;
                        pm <= ~pm; // 11 -> 12 toggles AM/PM
                    end
                    else begin
                        // Increment Hours BCD
                        if (hh[3:0] == 4'd9)
                            hh <= {hh[7:4] + 1, 4'd0};
                        else
                            hh <= hh + 1;
                    end
                end
                else begin
                    // Increment Minutes BCD
                    if (mm[3:0] == 4'd9)
                        mm <= {mm[7:4] + 1, 4'd0};
                    else
                        mm <= mm + 1;
                end
            end
            else begin
                // Increment Seconds BCD
                if (ss[3:0] == 4'd9)
                    ss <= {ss[7:4] + 1, 4'd0};
                else
                    ss <= ss + 1;
            end
        end
    end

endmodule

module top_module(
	input clk,
	input reset,
	output [3:1] ena,
	output reg [15:0] q);

	// Current BCD values for each digit
	wire [3:0] ones = q[3:0];
	wire [3:0] tens = q[7:4];
	wire [3:0] hundreds = q[11:8];
	wire [3:0] thousands = q[15:12];

	// Enable signals for digits 1, 2, 3 (tens, hundreds, thousands)
	reg [3:1] ena_reg;

	always @(posedge clk) begin
		if (reset) begin
			q <= 16'd0;
			ena_reg <= 3'd0;
		end else begin
			// Ones digit increments every cycle
			if (ones == 4'd9) begin
				q[3:0] <= 4'd0;
				ena_reg[1] <= 1'b1;  // Enable tens digit
			end else begin
				q[3:0] <= ones + 1;
				ena_reg[1] <= 1'b0;
			end

			// Tens digit increments when ones wraps
			if (tens == 4'd9) begin
				q[7:4] <= 4'd0;
				ena_reg[2] <= 1'b1;  // Enable hundreds digit
			end else begin
				q[7:4] <= tens + 1;
				ena_reg[2] <= 1'b0;
			end

			// Hundreds digit increments when tens wraps
			if (hundreds == 4'd9) begin
				q[11:8] <= 4'd0;
				ena_reg[3] <= 1'b1;  // Enable thousands digit
			end else begin
				q[11:8] <= hundreds + 1;
				ena_reg[3] <= 1'b0;
			end

			// Thousands digit increments when hundreds wraps
			if (thousands == 4'd9) begin
				q[15:12] <= 4'd0;
			end else begin
				q[15:12] <= thousands + 1;
			end
		end
	end

	assign ena = ena_reg;

endmodule

module top_module(
    input clk,
    input reset,
    output [3:1] ena,
    output reg [15:0] q);

    // ena[1]: Enable for Tens digit (q[7:4]) - Active when Ones (q[3:0]) is 9
    // ena[2]: Enable for Hundreds digit (q[11:8]) - Active when Tens (q[7:4]) is 9
    // ena[3]: Enable for Thousands digit (q[15:12]) - Active when Hundreds (q[11:8]) is 9
    assign ena[1] = (q[3:0] == 4'd9);
    assign ena[2] = (q[7:4] == 4'd9);
    assign ena[3] = (q[11:8] == 4'd9);

    always @(posedge clk) begin
        if (reset) begin
            q <= 16'd0;
        end else begin
            // Ones digit (q[3:0])
            if (q[3:0] == 4'd9)
                q[3:0] <= 4'd0;
            else
                q[3:0] <= q[3:0] + 1;

            // Tens digit (q[7:4])
            if (q[3:0] == 4'd9) begin
                if (q[7:4] == 4'd9)
                    q[7:4] <= 4'd0;
                else
                    q[7:4] <= q[7:4] + 1;
            end

            // Hundreds digit (q[11:8])
            if (q[7:4] == 4'd9) begin
                if (q[11:8] == 4'd9)
                    q[11:8] <= 4'd0;
                else
                    q[11:8] <= q[11:8] + 1;
            end

            // Thousands digit (q[15:12])
            if (q[11:8] == 4'd9) begin
