module top_module(
    input clk,
    input areset,
    input train_valid,
    input train_taken,
    output logic [1:0] state
);

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b01;
        end else if (train_valid) begin
            if (train_taken) begin
                // Increment, saturate at 3 (2'b11)
                if (state == 2'b11) begin
                    state <= 2'b11;
                end else begin
                    state <= state + 1;
                end
            end else begin
                // Decrement, saturate at 0 (2'b00)
                if (state == 2'b00) begin
                    state <= 2'b00;
                end else begin
                    state <= state - 1;
                end
            end
        end else begin
            // Hold state when not training
            state <= state;
        end
    end

endmodule

module top_module(
    input clk,
    input areset,
    input train_valid,
    input train_taken,
    output logic [1:0] state
);

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b01;
        end
        else if (train_valid) begin
            if (train_taken) begin
                if (state < 2'd3)
                    state <= state + 1;
            end
            else begin
                if (state > 2'd0)
                    state <= state - 1;
            end
        end
    end

endmodule

module top_module (
	input a,
	input b,
	input c,
	input d,
	output out_sop,
	output out_pos
);

// SOP: a'b'c + cd
// Covers minterms 2, 3, 7, 11, 15 (3 and 11 are don't cares)
assign out_sop = (~a & ~b & c) | (c & d);

// POS: (a+c) * (b'+c'+d) * (a'+c+d') * (a'+c'+d)
// Covers maxterms for 0s at 0,1,4,5,6,9,10,13,14
assign out_pos = (a | c) & (~b | ~c | d) & (~a | c | ~d) & (~a | ~c | d);

endmodule

module top_module (
	input a,
	input b,
	input c,
	input d,
	output out_sop,
	output out_pos
);

// SOP: a'b'c + cd
// Covers 1s at positions 2, 7, 15 using don't cares at 3, 8, 11, 12
assign out_sop = (~a & ~b & c) | (c & d);

// POS: (a + c)(b' + c' + d)(a' + c + d')(a' + b)
// Covers 0s at positions 0, 1, 4, 5, 6, 9, 10, 13, 14 using don't cares
assign out_pos = (a | c) & (~b | ~c | d) & (~a | c | ~d) & (~a | b);

endmodule

module top_module (
    input clk,
    input reset,
    input [3:1] s,
    output reg fr3,
    output reg fr2,
    output reg fr1,
    output reg dfr
);

    // Previous sensor state for detecting level changes
    reg [3:1] s_prev;

    // State encoding for water level:
    // 000 = Below s[1] (lowest)
    // 100 = Between s[2] and s[1]
    // 110 = Between s[3] and s[2]
    // 111 = Above s[3] (highest)

    // Level priority function (returns numeric level for comparison)
    function [1:0] get_level;
        input [3:1] sensors;
        begin
            if (sensors == 3'b111) get_level = 2;
            else if (sensors == 3'b110) get_level = 1;
            else if (sensors == 3'b100) get_level = 0;
            else if (sensors == 3'b000) get_level = -1;
            else get_level = -1; // Invalid state, treat as lowest
        end
    endfunction

    reg [1:0] current_level, prev_level;

    always @(posedge clk) begin
        if (reset) begin
            // Reset to low water level state (no sensors, all flow valves open)
            s_prev <= 3'b000;
            fr3 <= 1'b1;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Store current sensor state for next cycle comparison
            s_prev <= s;

            // Determine nominal flow rates based on current sensor state
            case (s)
                3'b000: begin // Below s[1]
                    fr3 <= 1'b1;
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                end
                3'b100: begin // Between s[2] and s[1]
                    fr3 <= 1'b0;
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                end
                3'b110: begin // Between s[3] and s[2]
                    fr3 <= 1'b0;
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                end
                3'b111: begin // Above s[3]
                    fr3 <= 1'b0;
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                end
                default: begin // Invalid sensor state
                    fr3 <= 1'b1;
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                end
            endcase

            // Determine if level is rising (previous level < current level)
            // This triggers supplemental flow valve (dfr)
            current_level = get_level(s);
            prev_level = get_level(s_prev);

            if (prev_level < current_level) begin
                dfr <= 1'b1;
            end else begin
                dfr <= 1'b0;
            end
        end
    end

endmodule

module top_module (
	input clk,
	input reset,
	input [3:1] s,
	output reg fr3,
	output reg fr2,
	output reg fr1,
	output reg dfr
);

reg [2:0] prev_s;

always @(posedge clk) begin
	if (reset) begin
		prev_s <= 3'b000;
		fr3 <= 1'b1;
		fr2 <= 1'b1;
		fr1 <= 1'b1;
		dfr <= 1'b1;
	end else begin
		// Determine nominal flow based on current sensor state
		case (s)
			3'b111: begin // Above s[3]
				fr3 <= 1'b0;
				fr2 <= 1'b0;
				fr1 <= 1'b0;
			end
			3'b011: begin // Between s[3] and s[2]
				fr3 <= 1'b0;
				fr2 <= 1'b0;
				fr1 <= 1'b1;
			end
			3'b001: begin // Between s[2] and s[1]
				fr3 <= 1'b0;
				fr2 <= 1'b1;
				fr1 <= 1'b1;
			end
			3'b000: begin // Below s[1]
				fr3 <= 1'b1;
				fr2 <= 1'b1;
				fr1 <= 1'b1;
			end
			default: begin
				fr3 <= 1'b1;
				fr2 <= 1'b1;
				fr1 <= 1'b1;
			end
		endcase

		// Determine if water level is rising (dfr)
		// Rising means current level > previous level
		case (s)
			3'b111: begin
				if (prev_s != 3'b111)
					dfr <= 1'b1;
				else
					dfr <= 1'b0;
			end
			3'b011: begin
				if (prev_s == 3'b001 || prev_s == 3'b000)
					dfr <= 1'b1;
				else
					dfr <= 1'b0;
			end
			3'b001: begin
				if (prev_s == 3'b000)
					dfr <= 1'b1;
				else
					dfr <= 1'b0;
			end
			3'b000: begin
				dfr <= 1'b0;
			end
			default: begin
				dfr <= 1'b0;
			end
		endcase

		// Update previous sensor state for next cycle
		prev_s <= s;
	end
end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:1] s,
    output reg fr3,
    output reg fr2,
    output reg fr1,
    output reg dfr
);

    // Register to store the previous sensor state
    reg [3:1] prev_s;

    // Temporary registers for level calculation
    reg [1:0] curr_level;
    reg [1:0] prev_level;

    always @(posedge clk) begin
        if (reset) begin
            // Reset state: equivalent to low water level for a long time
            // No sensors asserted (000), all outputs asserted (1)
            fr1 <= 1'b1;
            fr2 <= 1'b1;
            fr3 <= 1'b1;
            dfr <= 1'b1;
            prev_s <= 3'b000;
        end
        else begin
            // Calculate current water level based on sensor inputs s[3:1]
            // s[3] is highest sensor, s[1] is lowest.
            // Priority logic handles valid states: 111(3), 011(2), 001(1), 000(0)
            if (s[3]) 
                curr_level = 2'd3;
            else if (s[2]) 
                curr_level = 2'd2;
            else if (s[1]) 
                curr_level = 2'd1;
            else 
                curr_level = 2'd0;

            // Calculate previous water level based on stored prev_s
            if (prev_s[3]) 
                prev_level = 2'd3;
            else if (prev_s[2]) 
                prev_level = 2'd2;
            else if (prev_s[1]) 
                prev_level = 2'd1;
            else 
                prev_level = 2'd0;

            // Determine Nominal Flow Rates based on current level
            // Level 3 (Above s[3]): None
            // Level 2 (Between s[3], s[2]): fr1
            // Level 1 (Between s[2], s[1]): fr1, fr2
            // Level 0 (Below s[1]): fr1, fr2, fr3
            case (curr_level)
                2'd3: begin fr1 <= 0; fr2 <= 0; fr3 <= 0; end
                2'd2: begin fr1 <= 1; fr2 <= 0; fr3 <= 0; end
                2'd1: begin fr1 <= 1; fr2 <= 1; fr3 <= 0; end
                2'd0: begin fr1 <= 1; fr2 <= 1; fr3 <= 1; end
                default: begin fr1 <= 1; fr2 <= 1; fr3 <= 1; end
            endcase

            // Determine Supplemental Flow (dfr)
            // Open if previous level was lower than current level (rising edge of level)
            if (curr_level > prev_level)
                dfr <= 1'b1;
            else
                dfr <= 1'b0;

            // Update previous sensor state for next cycle
            prev_s <= s;
        end
    end

endmodule

module top_module (
	input c,
	input d,
	output [3:0] mux_in
);

// mux_in[0] = c OR d
// Using 2-to-1 MUX: select = c, input0 = d, input1 = 1
assign mux_in[0] = c ? 1'b1 : d;

// mux_in[1] = 0 (constant)
assign mux_in[1] = 1'b0;

// mux_in[2] = c AND d
// Using 2-to-1 MUX: select = c, input0 = 0, input1 = d
assign mux_in[2] = c ? d : 1'b0;

// mux_in[3] = c OR NOT d
// Using 2-to-1 MUX: select = d, input0 = 1, input1 = c
assign mux_in[3] = d ? c : 1'b1;

endmodule

module top_module (
	input c,
	input d,
	output [3:0] mux_in
);

	// mux_in[0] corresponds to ab=00
	// Values for cd=00,01,11,10 are 0,1,1,1
	// Logic: c | d
	// Implemented as: if d then 1 else c
	assign mux_in[0] = d ? 1'b1 : c;

	// mux_in[1] corresponds to ab=01
	// Values for cd=00,01,11,10 are 0,0,0,0
	// Logic: 0
	assign mux_in[1] = 1'b0;

	// mux_in[2] corresponds to ab=10
	// Values for cd=00,01,11,10 are 1,0,1,1
	// Logic: c | ~d
	// Implemented as: if d then c else 1
	assign mux_in[2] = d ? c : 1'b1;

	// mux_in[3] corresponds to ab=11
	// Values for cd=00,01,11,10 are 0,0,1,0
	// Logic: c & d
	// Implemented as: if d then c else 0
	assign mux_in[3] = d ? c : 1'b0;

endmodule

module top_module (
    input c,
    input d,
    output [3:0] mux_in
);
    // mux_in[0] corresponds to ab=00 (Col 00 of K-map)
    // Col 00 values for cd=00,01,11,10 are 0,1,1,1 -> c + d
    // Implemented as: if c=1 then 1 else d
    assign mux_in[0] = c ? 1 : d;

    // mux_in[1] corresponds to ab=01 (Col 01 of K-map)
    // Col 01 values are 0,0,0,0 -> 0
    assign mux_in[1] = 0;

    // mux_in[2] corresponds to ab=10 (Col 10 of K-map)
    // Col 10 values for cd=00,01,11,10 are 1,0,1,1 -> c + ~d
    // Implemented as: if d=0 then 1 else c
