module top_module (
    input clk,
    input areset,
    input x,
    output z
);
    // One-hot encoding for states
    localparam [1:0] A = 2'b01;
    localparam [1:0] B = 2'b10;

    // State register
    reg [1:0] current_state;
    reg [1:0] next_state;

    // Sequential Logic: State Register with Asynchronous Active-High Reset
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational Logic: Next State Determination
    always @(*) begin
        // Default assignment to prevent latch inference
        next_state = A;

        case (current_state)
            A: begin
                if (x == 1'b0) begin
                    next_state = A;
                end else begin // x == 1'b1
                    next_state = B;
                end
            end
            B: begin
                // Once in state B, stay in state B
                next_state = B;
            end
            default: begin
                next_state = A;
            end
        endcase
    end

    // Combinational Logic: Mealy Output
    // State A: z = x (0->0, 1->1)
    // State B: z = ~x (0->1, 1->0)
    assign z = (current_state == A) ? x : ~x;

endmodule

