module top_module (
    input clk,
    input areset,
    input x,
    output z
);
    // One-hot encoding for states A and B
    // state_A = 1'b1, state_B = 1'b0 -> State A
    // state_A = 1'b0, state_B = 1'b1 -> State B
    reg state_A;
    reg state_B;

    // Next state logic variables
    reg next_A;
    reg next_B;

    // Combinational logic for Next State
    always @(*) begin
        // Transitions from State A (state_A = 1)
        // If x = 0, next state is A (next_A = 1)
        // If x = 1, next state is B (next_B = 1)
        next_A = state_A & ~x;

        // Transitions from State B (state_B = 1)
        // Always stays in B (next_B = 1) regardless of x
        // Also captures transition from A to B when x = 1
        next_B = (state_A & x) | state_B;
    end

    // Sequential logic for State Registers
    // Asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state_A <= 1'b1;
            state_B <= 1'b0;
        end else begin
            state_A <= next_A;
            state_B <= next_B;
        end
    end

    // Output logic (Mealy machine: depends on current state and input)
    // State A: x=0 -> z=0, x=1 -> z=1 (z = x)
    // State B: x=0 -> z=1, x=1 -> z=0 (z = ~x)
    assign z = (state_A & x) | (state_B & ~x);

endmodule

