module top_module (
    input clk,
    input areset,
    input x,
    output z
);

    // State encoding for Moore machine
    // PASS_0: Pass-through mode, previous input was 0 (Output 0)
    // PASS_1: Pass-through mode, previous input was 1 (Output 1)
    // INVERT_0: Invert mode, previous input was 0 (Output 1)
    // INVERT_1: Invert mode, previous input was 1 (Output 0)
    parameter PASS_0 = 2'b00;
    parameter PASS_1 = 2'b01;
    parameter INVERT_0 = 2'b10;
    parameter INVERT_1 = 2'b11;

    reg [1:0] state, next_state;
    reg z;

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= PASS_0;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            PASS_0: begin
                if (x) next_state = PASS_1;
                else next_state = PASS_0;
            end
            PASS_1: begin
                if (x) next_state = INVERT_1;
                else next_state = INVERT_0;
            end
            INVERT_0: begin
                if (x) next_state = INVERT_1;
                else next_state = INVERT_0;
            end
            INVERT_1: begin
                if (x) next_state = INVERT_1;
                else next_state = INVERT_0;
            end
            default: next_state = PASS_0;
        endcase
    end

    // Output logic (Moore: depends only on state)
    always @(*) begin
        case (state)
            PASS_0: z = 1'b0;
            PASS_1: z = 1'b1;
            INVERT_0: z = 1'b1;
            INVERT_1: z = 1'b0;
            default: z = 1'b0;
        endcase
    end

endmodule

module top_module (
	input clk,
	input areset,
	input x,
	output z
);
    // State definitions
    localparam PASS = 1'b0;
    localparam INVERT = 1'b1;

    reg state;
    reg z;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            // Asynchronous reset: Stop conversion, reset state and output
            state <= PASS;
            z <= 1'b0;
        end
        else begin
            // Moore State Machine Logic
            // Output z is registered, so it depends on the state at the clock edge.
            // The value of z for the next cycle is determined by current state and input x.
            case (state)
                PASS: begin
                    // If we haven't seen a '1' yet, pass x through.
                    // If x is '1', transition to INVERT state for next cycle.
                    if (x == 1'b1)
                        state <= INVERT;
                    else
                        state <= PASS;
                    z <= x;
                end
                INVERT: begin
                    // If we have seen a '1', invert all subsequent bits.
                    state <= INVERT;
                    z <= ~x;
                end
            endcase
        end
    end
endmodule

module top_module(
