		if (reset) begin
			out <= 32'b0;
			in_prev <= 32'b0;
		end
		else begin
			// Detect falling edge (1 to 0 transition) for each bit
			// Set output bit to 1 if transition detected, otherwise maintain current state
			out <= out | (in_prev & ~in);
			// Store current input for next cycle comparison
			in_prev <= in;
		end
	end

