	localparam [2:0] S0 = 3'd0;  // Initial/reset state (equivalent to previous input = 0)
	localparam [2:0] S1 = 3'd1;  // 1 consecutive 1 seen
	localparam [2:0] S2 = 3'd2;  // 2 consecutive 1s seen
	localparam [2:0] S3 = 3'd3;  // 3 consecutive 1s seen
	localparam [2:0] S4 = 3'd4;  // 4 consecutive 1s seen
	localparam [2:0] S5 = 3'd5;  // 5 consecutive 1s seen
	localparam [2:0] S6 = 3'd6;  // 6 consecutive 1s seen
	localparam [2:0] S7 = 3'd7;  // 7+ consecutive 1s seen (error state)

	reg [2:0] state, next_state;

	// Synchronous state register with active-high reset
	always @(posedge clk) begin
		if (reset)
			state <= S0;
		else
			state <= next_state;
	end

	// Next state logic
	always @(*) begin
		case (state)
			S0: next_state = (in) ? S1 : S0;
			S1: next_state = (in) ? S2 : S0;
			S2: next_state = (in) ? S3 : S0;
			S3: next_state = (in) ? S4 : S0;
			S4: next_state = (in) ? S5 : S0;
			S5: next_state = (in) ? S6 : S0;
			S6: next_state = (in) ? S7 : S0;
			S7: next_state = S7;  // Stay in error state
			default: next_state = S0;
		endcase
	end

	// Moore output logic (outputs depend only on current state)
	// Outputs are asserted for one full clock cycle after the condition is met
	always @(*) begin
		disc = 0;
		flag = 0;
		err = 0;

		case (state)
			S5: disc = 1;  // 5 consecutive 1s detected (bit stuffing)
			S6: flag = 1;  // 6 consecutive 1s detected (frame flag)
			S7: err = 1;   // 7+ consecutive 1s detected (error)
