    reg [1:0] state;
    reg [1:0] next_state;

    // Sequential Logic: State updates on clock edge
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Combinational Logic: Next state determination
    always @(*) begin
        case (state)
            IDLE: begin
                // Discard bytes until we see one with in[3] == 1
                if (in[3])
                    next_state = B1;
                else
                    next_state = IDLE;
            end
            B1: begin
                // Byte 1 received, assume next is Byte 2
                next_state = B2;
            end
            B2: begin
                // Byte 2 received, assume next is Byte 3
                next_state = B3;
            end
            B3: begin
                // Byte 3 received. Signal done in this cycle.
                // Return to IDLE to search for next message start.
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output Logic
    // done is asserted in the cycle where state is B3 (immediately after 3rd byte received)
    assign done = (state == B3);

endmodule

module top_module (
    input clk,
    input [7:0] in,
    input reset,
    output done
);

    // State encoding
    parameter IDLE = 2'b00;
    parameter BYTE1 = 2'b01;
    parameter BYTE2 = 2'b10;
    parameter BYTE3 = 2'b11;

    // State registers
    reg [1:0] state, next_state;

    // Combinational logic for next state determination
    always @(*) begin
        case (state)
            IDLE: begin
                // Discard bytes until in[3] == 1
                if (in[3])
                    next_state = BYTE1;
                else
                    next_state = IDLE;
            end
            BYTE1: begin
                // Byte 1 received, wait for Byte 2
                next_state = BYTE2;
            end
            BYTE2: begin
                // Byte 2 received, wait for Byte 3
                next_state = BYTE3;
            end
            BYTE3: begin
                // Byte 3 received, signal done in this cycle.
                // Check next byte for start of new message immediately.
                if (in[3])
                    next_state = BYTE1;
                else
                    next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Sequential logic for state update
    always @(posedge clk) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Output logic: done is asserted in the cycle immediately after the third byte
    // (which is the cycle where the FSM is in BYTE3 state)
    assign done = (state == BYTE3);

endmodule

module top_module (
    input in,
    input [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
);

    // Next State Logic
    // S0 is entered from S0, S1, S2, S3, S4, S7, S8, S9 when in == 0
    assign next_state[0] = (state[0] | state[1] | state[2] | state[3] | state[4] | state[7] | state[8] | state[9]) & ~in;

    // S1 is entered from S0, S8, S9 when in == 1
    assign next_state[1] = (state[0] | state[8] | state[9]) & in;

    // S2 is entered from S1 when in == 1
    assign next_state[2] = state[1] & in;

    // S3 is entered from S2 when in == 1
    assign next_state[3] = state[2] & in;

    // S4 is entered from S3 when in == 1
    assign next_state[4] = state[3] & in;

    // S5 is entered from S4 when in == 1
    assign next_state[5] = state[4] & in;

    // S6 is entered from S5 when in == 1
    assign next_state[6] = state[5] & in;

    // S7 is entered from S6, S7 when in == 1
    assign next_state[7] = (state[6] | state[7]) & in;

    // S8 is entered from S5 when in == 0
    assign next_state[8] = state[5] & ~in;

    // S9 is entered from S6 when in == 0
    assign next_state[9] = state[6] & ~in;

    // Output Logic
    // out1 is 1 for S8 and S9
    assign out1 = state[8] | state[9];

    // out2 is 1 for S7 and S9
    assign out2 = state[7] | state[9];

