module top_module (
	input in,
	input [9:0] state,
	output [9:0] next_state,
	output out1,
	output out2);

    // Next State Logic
    // S0, S1, S2, S3, S4, S7, S8, S9 transition to S0 when in == 0
    assign next_state[0] = (state[0] | state[1] | state[2] | state[3] | state[4] | state[7] | state[8] | state[9]) & ~in;

    // S0, S8, S9 transition to S1 when in == 1
    assign next_state[1] = (state[0] | state[8] | state[9]) & in;

    // S1 transitions to S2 when in == 1
    assign next_state[2] = state[1] & in;

    // S2 transitions to S3 when in == 1
    assign next_state[3] = state[2] & in;

    // S3 transitions to S4 when in == 1
    assign next_state[4] = state[3] & in;

    // S4 transitions to S5 when in == 1
    assign next_state[5] = state[4] & in;

    // S5 transitions to S6 when in == 1
    assign next_state[6] = state[5] & in;

    // S6, S7 transition to S7 when in == 1
    assign next_state[7] = (state[6] | state[7]) & in;

    // S5 transitions to S8 when in == 0
    assign next_state[8] = state[5] & ~in;

    // S6 transitions to S9 when in == 0
    assign next_state[9] = state[6] & ~in;

    // Output Logic
    // out1 is 1 for S8, S9
    assign out1 = state[8] | state[9];

    // out2 is 1 for S7, S9
    assign out2 = state[7] | state[9];

