module top_module (
    input in,
    input [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
);

    // Next State Logic (One-Hot Encoding)
    // next_state[0] (S0): Entered from S0, S1, S2, S3, S4, S7, S8, S9 when in=0
    assign next_state[0] = ~in & (state[0] | state[1] | state[2] | state[3] | state[4] | state[7] | state[8] | state[9]);

    // next_state[1] (S1): Entered from S0, S8, S9 when in=1
    assign next_state[1] = in & (state[0] | state[8] | state[9]);

    // next_state[2] (S2): Entered from S1 when in=1
    assign next_state[2] = in & state[1];

    // next_state[3] (S3): Entered from S2 when in=1
    assign next_state[3] = in & state[2];

    // next_state[4] (S4): Entered from S3 when in=1
    assign next_state[4] = in & state[3];

    // next_state[5] (S5): Entered from S4 when in=1
    assign next_state[5] = in & state[4];

    // next_state[6] (S6): Entered from S5 when in=1
    assign next_state[6] = in & state[5];

    // next_state[7] (S7): Entered from S6, S7 when in=1
    assign next_state[7] = in & (state[6] | state[7]);

    // next_state[8] (S8): Entered from S5 when in=0
    assign next_state[8] = ~in & state[5];

    // next_state[9] (S9): Entered from S6 when in=0
    assign next_state[9] = ~in & state[6];

    // Output Logic
    // out1 is high in S8 (1,0) and S9 (1,1)
    assign out1 = state[8] | state[9];

    // out2 is high in S7 (0,1) and S9 (1,1)
    assign out2 = state[7] | state[9];

endmodule

module top_module (
    input clk,
    input [7:0] in,
    input reset,
    output [23:0] out_bytes,
    output done
);

    // State encoding
    parameter S_SEARCH = 2'b00;
    parameter S_BYTE1 = 2'b01;
    parameter S_BYTE2 = 2'b10;
    parameter S_DONE = 2'b11;

    reg [1:0] state;
    reg [23:0] msg_reg;

    // Sequential Logic for State and Data
    always @(posedge clk) begin
        if (reset) begin
            state <= S_SEARCH;
            msg_reg <= 24'd0;
        end else begin
            case (state)
                S_SEARCH:
                    if (in[3]) begin
                        msg_reg[23:16] <= in;
                        state <= S_BYTE1;
                    end else begin
                        state <= S_SEARCH;
                    end
                S_BYTE1:
                    msg_reg[15:8] <= in;
                    state <= S_BYTE2;
                S_BYTE2:
                    msg_reg[7:0] <= in;
                    state <= S_DONE;
                S_DONE:
                    state <= S_SEARCH;
            endcase
        end
    end

    // Output Logic
    assign done = (state == S_DONE);
    assign out_bytes = msg_reg;

endmodule

module top_module (
	input clk,
	input in,
	input reset,
	output done
);

    // State encoding
    parameter IDLE = 2'd0;
    parameter DATA = 2'd1;
    parameter STOP = 2'd2;
    parameter ERR_WAIT = 2'd3;

    reg [1:0] state, next_state;
    reg [2:0] data_count, next_data_count;
    reg done;
    reg next_done;

    // Synchronous Reset and State Update
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            data_count <= 3'd0;
            done <= 1'b0;
        end else begin
            state <= next_state;
            data_count <= next_data_count;
            done <= next_done;
        end
    end

    // Next State Logic
    always @(*) begin
        case (state)
            IDLE: begin
                // Wait for start bit (0)
                if (in == 1'b0) begin
                    next_state = DATA;
                    next_data_count = 3'd0;
                end else begin
                    next_state = IDLE;
                    next_data_count = data_count;
                end
            end
            DATA: begin
                // Count 8 data bits
                if (data_count < 3'd7) begin
                    next_state = DATA;
                    next_data_count = data_count + 3'd1;
                end else begin
                    // After 8 bits, check stop bit
                    next_state = STOP;
                    next_data_count = 3'd0;
                end
            end
            STOP: begin
                // Check stop bit (1)
                if (in == 1'b1) begin
                    // Valid stop bit received
                    next_state = IDLE;
                    next_data_count = 3'd0;
                end else begin
                    // Stop bit error, wait for line to go high
                    next_state = ERR_WAIT;
                    next_data_count = 3'd0;
                end
            end
            ERR_WAIT: begin
                // Wait for logic 1 (stop bit/idle)
                if (in == 1'b1) begin
                    next_state = IDLE;
                    next_data_count = 3'd0;
                end else begin
                    next_state = ERR_WAIT;
                    next_data_count = 3'd0;
                end
            end
            default: begin
                next_state = IDLE;
                next_data_count = 3'd0;
            end
        endcase
    end

    // Done Logic
    // Assert done when a valid stop bit is detected in STOP state
    always @(*) begin
        if (state == STOP && in == 1'b1)
            next_done = 1'b1;
        else
            next_done = 1'b0;
    end

endmodule

module top_module (
    input clk,
    input in,
    input reset,
    output done
);

    localparam IDLE = 2'b00;
    localparam DATA = 2'b01;
    localparam CHECK_STOP = 2'b10;
    localparam ERROR_WAIT = 2'b11;

    reg [1:0] state, next_state;
    reg [2:0] bit_count, next_bit_count;
    reg done_reg;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            bit_count <= 0;
            done_reg <= 0;
        end else begin
            state <= next_state;
            bit_count <= next_bit_count;
            // Assert done when Stop bit is verified (1) in CHECK_STOP state
            done_reg <= (state == CHECK_STOP && in == 1);
        end
    end

    always @(*) begin
        next_state = state;
        next_bit_count = bit_count;

        case (state)
            IDLE: begin
                // Wait for Start bit (0)
                if (in == 0) begin
                    next_state = DATA;
                    next_bit_count = 0;
                end
            end

            DATA: begin
                // Receive 8 data bits
                if (bit_count == 7) begin
                    next_state = CHECK_STOP;
                    next_bit_count = 0;
                end else begin
                    next_bit_count = bit_count + 1;
                end
            end

            CHECK_STOP: begin
                // Verify Stop bit (1)
                if (in == 1) begin
                    next_state = IDLE;
                end else begin
                    next_state = ERROR_WAIT;
                end
                next_bit_count = 0;
            end

            ERROR_WAIT: begin
                // Wait for a 1 (Stop bit or Idle) before attempting next byte
                if (in == 1) begin
                    next_state = IDLE;
                end
                next_bit_count = 0;
            end
        endcase
    end

    assign done = done_reg;

endmodule

module top_module (
    input clk,
    input in,
    input reset,
    output done
);

    // State definitions
    localparam IDLE  = 4'd0;
    localparam RX0   = 4'd1;
    localparam RX1   = 4'd2;
    localparam RX2   = 4'd3;
    localparam RX3   = 4'd4;
    localparam RX4   = 4'd5;
    localparam RX5   = 4'd6;
    localparam RX6   = 4'd7;
    localparam RX7   = 4'd8;
    localparam STOP  = 4'd9;
    localparam ERROR = 4'd10;

    reg [3:0] state, next_state;

    // Synchronous Reset and State Update
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next State Logic
    always @(*) begin
        case (state)
            IDLE: begin
                // Wait for Start Bit (0). Idle line is 1.
                if (in == 1'b0)
                    next_state = RX0;
                else
                    next_state = IDLE;
            end
            RX0:  next_state = RX1;
            RX1:  next_state = RX2;
            RX2:  next_state = RX3;
            RX3:  next_state = RX4;
            RX4:  next_state = RX5;
            RX5:  next_state = RX6;
            RX6:  next_state = RX7;
            RX7:  next_state = STOP;
            STOP: begin
                // Check Stop Bit (1)
                if (in == 1'b1)
                    next_state = IDLE; // Valid Stop Bit, byte received
                else
                    next_state = ERROR; // Stop Bit Error (0 found)
            end
            ERROR: begin
                // Wait for a Stop Bit (1) to resync before attempting next byte
                if (in == 1'b1)
                    next_state = IDLE;
                else
                    next_state = ERROR;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output Logic
    // done is active high when Stop Bit is correctly received (State is STOP and in is 1)
    assign done = (state == STOP) && (in == 1'b1);

endmodule

module top_module (
    input clk,
    input in,
    input reset,
    output done
);

    // Internal register for done output to keep interface as wire
    reg done_reg;
    assign done = done_reg;

    // State Encoding
    localparam IDLE  = 4'd0;
    localparam D0    = 4'd1;
    localparam D1    = 4'd2;
    localparam D2    = 4'd3;
    localparam D3    = 4'd4;
    localparam D4    = 4'd5;
    localparam D5    = 4'd6;
    localparam D6    = 4'd7;
    localparam D7    = 4'd8;
    localparam STOP  = 4'd9;
    localparam ERROR = 4'd10;

    reg [3:0] state, next_state;

    // Sequential Logic: State Register and Done Output
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            done_reg <= 1'b0;
        end else begin
            state <= next_state;
            // Pulse done when Stop bit is verified (State STOP and in is 1)
            if (state == STOP && in == 1'b1) begin
                done_reg <= 1'b1;
            end else begin
                done_reg <= 1'b0;
            end
        end
    end

    // Combinational Logic: Next State Determination
    always @(*) begin
        case (state)
            IDLE: begin
                // Wait for Start bit (0)
                if (in == 1'b0) next_state = D0;
                else next_state = IDLE;
            end
            D0: next_state = D1;
            D1: next_state = D2;
            D2: next_state = D3;
            D3: next_state = D4;
            D4: next_state = D5;
            D5: next_state = D6;
            D6: next_state = D7;
            D7: next_state = STOP;
            STOP: begin
                // Verify Stop bit (1)
                if (in == 1'b1) next_state = IDLE; // Success
                else next_state = ERROR;           // Error
            end
            ERROR: begin
                // Wait for a Stop bit (1) to re-sync
                if (in == 1'b1) next_state = IDLE;
                else next_state = ERROR;
            end
            default: next_state = IDLE;
        endcase
    end

endmodule

module top_module (
	input clk,
	input in,
	input reset,
	output done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam RX   = 2'b01;
    localparam STOP = 2'b10;
    localparam ERR  = 2'b11;

    // State registers
    reg [1:0] state, next_state;

    // Bit counter for data bits (0 to 7)
    reg [2:0] bit_count;

    // Done output register
    reg done_reg;
    assign done = done_reg;

    // Synchronous Reset and State/Register Updates
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            bit_count <= 3'd0;
            done_reg <= 1'b0;
        end else begin
            state <= next_state;

            // Update bit_count
            if (state == IDLE && in == 1'b0) begin
                bit_count <= 3'd0;
            end else if (state == RX) begin
                bit_count <= bit_count + 1'b1;
            end

            // Update done signal
            if (state == STOP && in == 1'b1) begin
                done_reg <= 1'b1;
            end else begin
                done_reg <= 1'b0;
            end
        end
    end

    // Next State Logic
    always @(*) begin
        next_state = state; // Default: stay in current state
        case (state)
            IDLE: begin
                // Wait for Start Bit (0)
                if (in == 1'b0)
                    next_state = RX;
                else
                    next_state = IDLE;
            end
            RX: begin
                // Receive 8 Data Bits
                // We count 0 to 7 (8 cycles)
                if (bit_count == 3'd7)
                    next_state = STOP;
                else
                    next_state = RX;
            end
            STOP: begin
                // Verify Stop Bit (1)
                if (in == 1'b1)
                    next_state = IDLE;
                else
                    next_state = ERR;
            end
            ERR: begin
                // Error Recovery: Wait for a Stop Bit (1)
                if (in == 1'b1)
                    next_state = IDLE;
                else
                    next_state = ERR;
            end
            default: next_state = IDLE;
        endcase
    end

endmodule

module top_module (
	input clk,
	input in,
	input reset,
	output [7:0] out_byte,
	output done
);

	// State encoding
	localparam IDLE = 3'd0;
	localparam START = 3'd1;
	localparam DATA0 = 3'd2;
	localparam DATA1 = 3'd3;
	localparam DATA2 = 3'd4;
	localparam DATA3 = 3'd5;
	localparam DATA4 = 3'd6;
	localparam DATA5 = 3'd7;
	localparam DATA6 = 3'd8;
	localparam DATA7 = 3'd9;
	localparam STOP = 3'd10;
	localparam ERROR = 3'd11;

	// State register
	reg [3:0] state, next_state;

	// Data register for received byte
	reg [7:0] data_reg, next_data;
	reg done_reg, next_done;
	reg [7:0] out_byte_reg;

	// State transition logic
	always @(*) begin
		next_state = state;
		next_data = data_reg;
		next_done = 0;
		out_byte_reg = out_byte_reg;

		case (state)
			IDLE: begin
				if (in == 0)
					next_state = START;
			end

			START: begin
				next_state = DATA0;
			end

			DATA0: begin
				next_data = {7'd0, in};
				next_state = DATA1;
			end

			DATA1: begin
				next_data = {6'd0, in, data_reg[0]};
				next_state = DATA2;
			end

			DATA2: begin
				next_data = {5'd0, in, data_reg[1:0]};
				next_state = DATA3;
			end

			DATA3: begin
				next_data = {4'd0, in, data_reg[2:0]};
				next_state = DATA4;
			end

			DATA4: begin
				next_data = {3'd0, in, data_reg[3:0]};
				next_state = DATA5;
			end

			DATA5: begin
				next_data = {2'd0, in, data_reg[4:0]};
				next_state = DATA6;
			end

			DATA6: begin
				next_data = {1'd0, in, data_reg[5:0]};
				next_state = DATA7;
			end

			DATA7: begin
				next_data = {in, data_reg[6:0]};
				next_state = STOP;
			end

			STOP: begin
				if (in == 1) begin
					next_state = IDLE;
					next_done = 1;
					out_byte_reg = data_reg;
				end
				else begin
					next_state = ERROR;
				end
			end

			ERROR: begin
				if (in == 1)
					next_state = IDLE;
			end

			default: begin
				next_state = IDLE;
			end
		endcase
	end

	// Sequential logic
	always @(posedge clk) begin
		if (reset) begin
			state <= IDLE;
			data_reg <= 8'd0;
			done_reg <= 0;
			out_byte_reg <= 8'd0;
		end
		else begin
			state <= next_state;
			data_reg <= next_data;
			done_reg <= next_done;
			out_byte_reg <= out_byte_reg;
		end
	end

	// Output assignment
	assign out_byte = out_byte_reg;
	assign done = done_reg;

endmodule

module top_module (
    input clk,
    input in,
    input reset,
    output [7:0] out_byte,
    output done
);

    // State definitions
    localparam IDLE = 2'd0;
    localparam DATA = 2'd1;
    localparam STOP = 2'd2;

    // State registers and internal variables
    reg [1:0] state, next_state;
    reg [7:0] byte_reg;
    reg [2:0] bit_cnt;
    reg recover; // Flag to indicate if we are waiting for a stop bit after a framing error
    reg done_reg;
    reg [7:0] out_byte_reg;

    // Sequential Logic
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            byte_reg <= 8'd0;
            bit_cnt <= 3'd0;
            recover <= 1'b0;
            done_reg <= 1'b0;
            out_byte_reg <= 8'd0;
        end else begin
            state <= next_state;

            // Capture data bits in DATA state
            if (state == DATA) begin
                byte_reg[bit_cnt] <= in;
                if (bit_cnt < 7)
                    bit_cnt <= bit_cnt + 1;
            end

            // Reset bit counter when entering DATA state from IDLE
            if (state == IDLE && next_state == DATA)
                bit_cnt <= 3'd0;

            // Logic for STOP state (checking stop bit or recovery)
            if (state == STOP) begin
                if (recover == 1'b0) begin
                    // Expecting a valid stop bit (1)
                    if (in == 1'b1) begin
                        done_reg <= 1'b1;
                        out_byte_reg <= byte_reg;
                        recover <= 1'b0;
                    end else begin
                        // Framing error (Stop bit was 0), enter recovery mode
                        recover <= 1'b1;
                        done_reg <= 1'b0;
                    end
                end else begin
                    // Recovery mode: waiting for a '1' to resync
                    if (in == 1'b1) begin
                        done_reg <= 1'b0;
                        recover <= 1'b0;
                    end else begin
                        done_reg <= 1'b0;
                        recover <= 1'b1;
                    end
                end
            end else begin
                // In IDLE or DATA, done is 0 and recover flag is cleared
                done_reg <= 1'b0;
                recover <= 1'b0;
            end
        end
    end

    // Combinational Logic for Next State
    always @(*) begin
        next_state = state;
        case (state)
            IDLE:
                // Detect start bit (0)
                if (in == 1'b0)
                    next_state = DATA;
                else
                    next_state = IDLE;

            DATA:
                // After 8 data bits (bit_cnt 0 to 7), go to STOP
                if (bit_cnt == 7)
                    next_state = STOP;
                else
                    next_state = DATA;

            STOP:
                // If stop bit found (1), go to IDLE
                // If stop bit not found (0), stay in STOP to wait for recovery
                if (in == 1'b1)
                    next_state = IDLE;
                else
                    next_state = STOP;
        endcase
    end

    // Assign outputs
    assign done = done_reg;
    assign out_byte = out_byte_reg;

endmodule

module top_module (
    input [3:0] in,
    output [2:0] out_both,
    output [3:1] out_any,
    output [3:0] out_different
);

    // out_both[i] is 1 if in[i] and in[i+1] are both 1
    assign out_both = {in[2] & in[3], in[1] & in[2], in[0] & in[1]};

    // out_any[i] is 1 if in[i] or in[i-1] is 1
    assign out_any = {in[3] | in[2], in[2] | in[1], in[1] | in[0]};

    // out_different[i] is 1 if in[i] is different from in[i+1] (with wrap around for i=3)
    assign out_different = {in[3] ^ in[0], in[2] ^ in[3], in[1] ^ in[2], in[0] ^ in[1]};

endmodule

module top_module (
    input [3:0] in,
    output [2:0] out_both,
    output [3:1] out_any,
    output [3:0] out_different
);

    // out_both[i]: in[i] AND in[i+1] (neighbour to the left = higher index)
    assign out_both[0] = in[0] & in[1];
    assign out_both[1] = in[1] & in[2];
    assign out_both[2] = in[2] & in[3];

    // out_any[i]: in[i] OR in[i-1] (neighbour to the right = lower index)
    assign out_any[1] = in[1] | in[0];
    assign out_any[2] = in[2] | in[1];
    assign out_any[3] = in[3] | in[2];

    // out_different[i]: in[i] XOR in[i+1] (neighbour to the left), with wrapping for i=3
    assign out_different[0] = in[0] ^ in[1];
    assign out_different[1] = in[1] ^ in[2];
    assign out_different[2] = in[2] ^ in[3];
    assign out_different[3] = in[3] ^ in[0];

endmodule

module top_module (
