module top_module (
    input [3:0] in,
    output [2:0] out_both,
    output [3:1] out_any,
    output [3:0] out_different
);

    // out_both[i]: in[i] AND in[i+1] (neighbour to the left/higher index)
    // out_both[2] = in[2] & in[3]
    // out_both[1] = in[1] & in[2]
    // out_both[0] = in[0] & in[1]
    assign out_both = {in[2] & in[3], in[1] & in[2], in[0] & in[1]};

    // out_any[i]: in[i] OR in[i-1] (neighbour to the right/lower index)
    // out_any[3] = in[3] | in[2]
    // out_any[2] = in[2] | in[1]
    // out_any[1] = in[1] | in[0]
    assign out_any = {in[3] | in[2], in[2] | in[1], in[1] | in[0]};

    // out_different[i]: in[i] XOR in[i+1] (neighbour to the left/higher index)
    // Wrap around for index 3: neighbour is in[0]
    // out_different[3] = in[3] ^ in[0]
    // out_different[2] = in[2] ^ in[3]
    // out_different[1] = in[1] ^ in[2]
    // out_different[0] = in[0] ^ in[1]
    assign out_different = {in[3] ^ in[0], in[2] ^ in[3], in[1] ^ in[2], in[0] ^ in[1]};

endmodule

module top_module (
    input [3:0] in,
    output [2:0] out_both,
    output [3:1] out_any,
    output [3:0] out_different
);

    // out_both[i]: Check if in[i] and left neighbor (in[i+1]) are both 1
    assign out_both[0] = in[0] & in[1];
    assign out_both[1] = in[1] & in[2];
    assign out_both[2] = in[2] & in[3];

    // out_any[i]: Check if in[i] or right neighbor (in[i-1]) is 1
    assign out_any[1] = in[1] | in[0];
    assign out_any[2] = in[2] | in[1];
    assign out_any[3] = in[3] | in[2];

    // out_different[i]: Check if in[i] is different from left neighbor (in[i+1]), wrapping around for i=3
    assign out_different[0] = in[0] ^ in[1];
    assign out_different[1] = in[1] ^ in[2];
    assign out_different[2] = in[2] ^ in[3];
    assign out_different[3] = in[3] ^ in[0];

endmodule

module top_module (
    input [99:0] in,
    output [98:0] out_both,
    output [99:1] out_any,
    output [99:0] out_different
);

    genvar i;

    // out_both[i] = 1 if both in[i] and its left neighbour in[i+1] are 1
    // Valid for i = 0 to 98
    generate
        for (i = 0; i < 99; i = i + 1) begin : gen_out_both
            assign out_both[i] = in[i] & in[i + 1];
        end
    endgenerate

    // out_any[i] = 1 if either in[i] or its right neighbour in[i-1] is 1
    // Valid for i = 1 to 99
    generate
        for (i = 1; i < 100; i = i + 1) begin : gen_out_any
            assign out_any[i] = in[i] | in[i - 1];
        end
    endgenerate

    // out_different[i] = 1 if in[i] differs from its left neighbour
    // For i = 0 to 98: left neighbour is in[i+1]
    // For i = 99: wraps around, left neighbour is in[0]
    generate
        for (i = 0; i < 99; i = i + 1) begin : gen_out_different
            assign out_different[i] = in[i] ^ in[i + 1];
        end
    endgenerate
    assign out_different[99] = in[99] ^ in[0];

endmodule

module top_module (
