module top_module (
    input [99:0] in,
    output [98:0] out_both,
    output [99:1] out_any,
    output [99:0] out_different
);

    // out_both[i] = in[i] & in[i+1] for i = 0 to 98
    // Checks if both the bit and its left neighbor are 1
    assign out_both = in[98:0] & in[99:1];

    // out_any[i] = in[i] | in[i-1] for i = 1 to 99
    // Checks if either the bit or its right neighbor is 1
    assign out_any = in[99:1] | in[98:0];

    // out_different[i] = in[i] ^ in[i+1] for i = 0 to 98
    // Checks if the bit is different from its left neighbor
    assign out_different[98:0] = in[98:0] ^ in[99:1];

    // Wrap-around: out_different[99] = in[99] ^ in[0]
    assign out_different[99] = in[99] ^ in[0];

endmodule

module top_module(
	input clk,
	input areset, 

	input predict_valid,
	input [6:0] predict_pc,
	output predict_taken, 
	output [6:0] predict_history,

	input train_valid,
	input train_taken,
	input train_mispredicted,
	input [6:0] train_history, 
	input [6:0] train_pc
);

    // Global History Register (7 bits)
    reg [6:0] ghr;

    // Pattern History Table (128 entries, 2 bits each)
    // Using a 1D array for the PHT
    reg [1:0] pht [0:127];

    // --- Prediction Logic (Combinational) ---
    // Calculate index using current GHR and PC (XOR hash)
    wire [6:0] predict_index = ghr ^ predict_pc;

    // Output prediction based on MSB of PHT entry (1 = Taken, 0 = Not Taken)
    assign predict_taken = pht[predict_index][1];

    // Output current GHR state
    assign predict_history = ghr;

    // --- Sequential Logic ---
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'd0;
            // Initialize PHT to all 0s (Strongly Not Taken)
            integer i;
            for (i = 0; i < 128; i = i + 1) begin
                pht[i] <= 2'd0;
            end
        end else begin
            // --- PHT Training Update ---
            if (train_valid) begin
                // Calculate index using training history and PC (XOR hash)
                wire [6:0] train_index = train_pc ^ train_history;

                // Saturating counter update
                if (train_taken) begin
                    if (pht[train_index] < 2'd3)
                        pht[train_index] <= pht[train_index] + 2'd1;
                end else begin
                    if (pht[train_index] > 2'd0)
                        pht[train_index] <= pht[train_index] - 2'd1;
                end
            end

            // --- GHR Update Logic ---
            // Priority: Training Mispredict Recovery > Prediction Update
            // If a misprediction is trained, we must recover the GHR state.
            // If not mispredicted, we update GHR based on the new prediction (if any).
            if (train_valid && train_mispredicted) begin
                // Recover GHR: Shift in actual outcome using history at fetch time
                // This restores the GHR to the state immediately after the mispredicting branch completes execution
                ghr <= {train_history[6:1], train_taken};
            end else if (predict_valid) begin
                // Standard update: Shift in predicted outcome
                ghr <= {ghr[6:1], predict_taken};
            end
            // Else ghr holds its value
        end
    end

endmodule

