module top_module (
    input clk,
    input areset,
    input x,
    output reg z
);

    parameter IDLE = 0;
    parameter CONVERTING = 1;

    reg [31:0] shift_reg;
    reg [31:0] result;
    reg [31:0] count;
    reg [1:0] state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= IDLE;
            shift_reg <= 0;
            result <= 0;
            count <= 0;
            z <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (!x) begin
                        state <= CONVERTING;
                        shift_reg <= 0;
                        result <= 0;
                        count <= 0;
                    end
                end
                CONVERTING: begin
                    shift_reg <= {shift_reg[30:0], x};
                    count <= count + 1;
                    if (count == 32) begin
                        state <= IDLE;
                        result <= ~shift_reg + 1;
                        z <= result[31];
                    end
                end
            endcase
        end
    end

endmodule

module top_module (
    input clk,
    input areset,
    input x,
    output reg z
);

reg [31:0] shift_reg;
reg [31:0] result;
reg sign_bit;
reg done;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        shift_reg <= 0;
        result <= 0;
        sign_bit <= 0;
        done <= 1;
        z <= 0;
    end else begin
        if (!done) begin
            shift_reg = {shift_reg[30:0], x};
            if (shift_reg == 32'b0) begin
                result = 0;
                done = 1;
            end else if (shift_reg[31]) begin
                result = ~shift_reg + 1;
                done = 1;
            end else begin
                result = shift_reg;
                done = 1;
            end
        end
        z <= result;
    end
end

endmodule

module top_module (
    input clk,
    input [7:0] in,
    input reset,
    output reg [23:0] out_bytes,
    output reg done
);
    parameter STATE_IDLE = 2'b00;
    parameter STATE_WAIT_1 = 2'b01;
    parameter STATE_WAIT_2 = 2'b10;

    reg [1:0] state;
    reg [2:0] byte_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= STATE_IDLE;
            byte_count <= 3'b000;
            out_bytes <= 24'b0;
            done <= 1'b0;
        end else begin
            case (state)
                STATE_IDLE: begin
                    if (in[3]) begin
                        state <= STATE_WAIT_1;
                        byte_count <= 3'b001;
                        out_bytes <= {in, 8'b0};
                    end
                end
                STATE_WAIT_1: begin
                    if (byte_count < 3'b110) begin
                        state <= STATE_WAIT_1;
                        byte_count <= byte_count + 1;
                        out_bytes <= {out_bytes[15:0], in};
                    end else begin
                        state <= STATE_WAIT_2;
                        byte_count <= 3'b001;
                        out_bytes <= {out_bytes[15:0], in};
                    end
                end
                STATE_WAIT_2: begin
                    if (byte_count < 3'b111) begin
                        state <= STATE_WAIT_2;
                        byte_count <= byte_count + 1;
                        out_bytes <= {out_bytes[7:0], in};
                    end else begin
                        state <= STATE_IDLE;
                        byte_count <= 3'b000;
                        out_bytes <= 24'b0;
                        done <= 1'b1;
                    end
                end
                default: state <= STATE_IDLE;
            endcase
        end
    end
endmodule

module top_module (
    input clk,
    input [7:0] in,
    input reset,
    output reg [23:0] out_bytes,
    output reg done
);
