    reg [1:0] state;
    reg [7:0] byte1, byte2, byte3;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= STATE_IDLE;
            byte1 <= 8'd0;
            byte2 <= 8'd0;
            byte3 <= 8'd0;
            out_bytes <= 24'd0;
            done <= 1'b0;
        end else begin
            case (state)
                STATE_IDLE: begin
                    if (in[3]) begin
                        state <= STATE_WAIT_1;
                        byte1 <= in;
                    end
                end
                STATE_WAIT_1: begin
                    state <= STATE_WAIT_2;
                    byte2 <= in;
                end
                STATE_WAIT_2: begin
                    state <= STATE_IDLE;
                    byte3 <= in;
                    out_bytes <= {byte1, byte2, byte3};
                    done <= 1'b1;
                end
                default: begin
                    state <= STATE_IDLE;
                end
            endcase
        end
    end
endmodule

