module top_module (
    input clk,
    input resetn,
    input [3:1] r,
    output reg [3:1] g
);

reg [1:0] state, next_state;

parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;

always @(posedge clk or negedge resetn) begin
    if (!resetn)
        state <= A;
    else
        state <= next_state;
end

always @(*) begin
    next_state = state;
    g = 4'b0000;

    case (state)
        A: begin
            if (r == 4'b0000)
                next_state = A;
            else if (r == 4'b0001)
                next_state = B;
            else if (r == 4'b0010)
                next_state = C;
            else if (r == 4'b0011)
                next_state = D;
        end
        B: begin
            if (r == 4'b0001 && g[1])
                next_state = B;
            else
                next_state = A;
        end
        C: begin
            if (r == 4'b0010 && g[2])
                next_state = C;
            else
                next_state = A;
        end
        D: begin
            next_state = A;
        end
        default: next_state = A;
    endcase

    case (state)
        A: begin
            if (r == 4'b0001)
                g[1] = 1;
            else if (r == 4'b0010)
                g[2] = 1;
            else if (r == 4'b0011)
                g[3] = 1;
        end
        B: begin
            if (r == 4'b0001)
                g[1] = 1;
        end
        C: begin
            if (r == 4'b0010)
                g[2] = 1;
        end
        default: ;
    endcase
end

endmodule

module top_module (
    input clk,
    input resetn,
    input [3:1] r,
    output reg [3:1] g
);

    // State definitions
    localparam A = 4'b0000;
    localparam B = 4'b0001;
    localparam C = 4'b0010;
    localparam D = 4'b0011;

    reg [1:0] state, next_state;

    // State register
    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            state <= A;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            A: begin
                if (r == 4'b0000)
                    next_state = A;
                else if (r[1] == 1'b1)
                    next_state = B;
                else if (r[2] == 1'b1)
                    next_state = C;
                else if (r[3] == 1'b1)
                    next_state = D;
            end
            B: begin
                if (g[1] == 1'b1 && r[1] == 1'b1)
                    next_state = B;
                else if (g[1] == 1'b1 && r[1] == 1'b0)
                    next_state = A;
            end
            C: begin
                if (g[2] == 1'b1 && r[2] == 1'b1)
                    next_state = C;
                else if (g[2] == 1'b1 && r[2] == 1'b0)
                    next_state = A;
            end
            D: begin
                next_state = A; // Device 3 has the lowest priority
            end
            default: next_state = A;
        endcase
    end

    // Output logic
    always @(*) begin
        g = 4'b0000;
        case (state)
            A: begin
                if (r[1] == 1'b1)
                    g[1] = 1'b1;
                else if (r[2] == 1'b1)
                    g[2] = 1'b1;
                else if (r[3] == 1'b1)
                    g[3] = 1'b1;
            end
            B: g[1] = 1'b1;
            C: g[2] = 1'b1;
            D: g[3] = 1'b1;
        endcase
    end

endmodule

module top_module (
	input clk,
	input [7:0] in,
	input reset,
	output reg done
);

reg [1:0] state;
reg [2:0] byte_count;

parameter IDLE = 2'b00;
parameter FIND_START = 2'b01;
parameter RECEIVE_BYTES = 2'b10;

always @(posedge clk or posedge reset) begin
	if (reset) begin
		state <= IDLE;
		byte_count <= 3'b000;
		done <= 1'b0;
	end else begin
		case (state)
			IDLE: begin
				if (in[3]) begin
					state <= FIND_START;
					byte_count <= 3'b001;
				end
			end
			FIND_START: begin
				if (byte_count == 3'b010) begin
					state <= RECEIVE_BYTES;
					byte_count <= 3'b001;
				end else if (!in[3]) begin
					state <= IDLE;
				end
			end
			RECEIVE_BYTES: begin
				if (byte_count == 3'b100) begin
					state <= IDLE;
					done <= 1'b1;
				end else begin
					byte_count <= byte_count + 1;
					done <= 1'b0;
				end
			end
		endcase
	end
end

endmodule

module top_module (
	input clk,
	input resetn,
	input x,
	input y,
	output reg f,
	output reg g
);

reg [1:0] state;
reg [2:0] x_count;
reg [1:0] y_count;

always @(posedge clk or negedge resetn) begin
	if (!resetn) begin
		state <= 2'b00; // State A
		f <= 0;
		g <= 0;
		x_count <= 3'b000;
		y_count <= 2'b00;
	end else begin
		case (state)
			2'b00: // State A
				begin
					f <= 0;
					g <= 0;
					if (x == 1 && y == 1) begin
						state <= 2'b01; // Move to State B
					end
				end
			2'b01: // State B
				begin
					f <= 1;
					g <= 0;
					if (x == 1 && x_count < 3) begin
						x_count <= x_count + 1;
					end else if (y == 1 && y_count < 2) begin
						y_count <= y_count + 1;
					end else if (x_count == 3 || y_count == 2) begin
						state <= 2'b10; // Move to State C
					end
				end
			2'b10: // State C
				begin
					f <= 1;
					g <= (y_count == 2);
				end
		endcase
	end
end

endmodule

