    reg [1:0] current_state;
    reg [1:0] next_state;
    reg [1:0] w_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_A;
            z <= 0;
        end else begin
            current_state <= next_state;
            if (current_state == STATE_B && w_count == 2)
                z <= 1;
            else
                z <= 0;
