    end

    always @(*) begin
        next_state = current_state;
        w_count = 0;
        case (current_state)
            STATE_A: begin
                if (s)
                    next_state = STATE_B;
            end
            STATE_B: begin
                w_count = (w_count << 1) | w;
                if (w_count == 3 || w_count == 6)
                    next_state = STATE_B;
                else if (w_count == 5)
                    next_state = STATE_A;
            end
        endcase
    end
