                        state <= COUNT_1;
                        count <= 3'b001;
                    end
                end
                COUNT_1: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
                    end else if (count < 5) begin
                        state <= COUNT_1;
                        count <= count + 1;
                    end else begin
                        state <= COUNT_2;
                        count <= 3'b001;
                    end
                end
                COUNT_2: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
