                        state <= COUNT_2;
                        count <= count + 1;
                    end else begin
                        state <= COUNT_3;
                        count <= 3'b001;
                    end
                end
                COUNT_3: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
                    end else if (count < 5) begin
                        state <= COUNT_3;
                        count <= count + 1;
                    end else begin
                        state <= COUNT_4;
                        count <= 3'b001;
                    end
                end
                COUNT_4: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
