    reg [7:0] data_reg;
    reg [2:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            data_reg <= 8'b0;
            bit_count <= 3'b0;
            out_byte <= 8'b0;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= START_BIT;
                        bit_count <= 3'b0;
                    end
                end
                START_BIT: begin
                    if (bit_count == 3'b0) begin
                        state <= DATA_BITS;
                    end else begin
                        bit_count <= bit_count + 1;
                    end
                end
                DATA_BITS: begin
                    if (bit_count < 3'b1000) begin
                        data_reg[bit_count] <= in;
                        bit_count <= bit_count + 1;
                    end else begin
                        state <= STOP_BIT;
                    end
                end
                STOP_BIT: begin
                    if (in == 1'b1) begin
                        out_byte <= data_reg;
                        done <= 1'b1;
                        state <= IDLE;
                    end else begin
                        state <= START_BIT;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

module top_module(
    input clk,
    input areset, 

    input predict_valid,
    input [6:0] predict_pc,
    output reg predict_taken, 
    output reg [6:0] predict_history,

    input train_valid,
    input train_taken,
    input train_mispredicted,
    input [6:0] train_history, 
    input [6:0] train_pc
);

    parameter PHT_SIZE = 128;
    parameter HISTORY_BITS = 7;

    reg [HISTORY_BITS-1:0] global_branch_history;
    reg [HISTORY_BITS-1:0] pht [0:PHT_SIZE-1];
    reg [1:HISTORY_BITS-1] pht_state [0:PHT_SIZE-1];

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            global_branch_history <= 0;
            for (int i = 0; i < PHT_SIZE; i++) begin
                pht[i] <= 0;
                pht_state[i] <= 2'b00;
            end
        end else begin
            if (train_valid) begin
                int index;
                index = predict_pc ^ global_branch_history;
                pht[index] <= train_history;
                if (train_mispredicted) begin
                    global_branch_history <= train_history;
                end
            end

            if (predict_valid) begin
                int index;
                index = predict_pc ^ global_branch_history;
                predict_taken <= (pht_state[index] == 2'b11);
                predict_history <= pht[index];
            end
        end
    end

endmodule

module top_module(
