reg [3:0] bcd_mm;
reg [3:0] bcd_hh;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        pm <= 0;
        bcd_ss <= 8'd0;
        bcd_mm <= 8'd0;
        bcd_hh <= 8'd12;
    end else begin
        if (ena) begin
            bcd_ss <= bcd_ss + 1;
            if (bcd_ss == 8'd60) begin
                bcd_ss <= 8'd0;
                bcd_mm <= bcd_mm + 1;
                if (bcd_mm == 8'd60) begin
                    bcd_mm <= 8'd0;
                    bcd_hh <= bcd_hh + 1;
                    if (bcd_hh == 8'd13) begin
                        bcd_hh <= 8'd1;
                    end
                end
            end
        end
    end
end

always @(*) begin
    if (bcd_hh > 8'd12) begin
        pm = 1;
        hh = {4'b0, bcd_hh - 8'd12};
    end else begin
        pm = 0;
        hh = {4'b0, bcd_hh};
    end
    mm = {4'b0, bcd_mm};
    ss = {4'b0, bcd_ss};
