            if (min_cnt == 4'b1111) begin
                min_cnt <= 4'b0000;
                hr_cnt <= hr_cnt + 1;
                if (hr_cnt == 4'b1111) begin
                    hr_cnt <= 4'b0000;
                    pm <= ~pm;
                end
            end
        end
    end
end

