        q_xor <= q_xor_d;
        q_and <= q_and_d;
        q_or <= q_or_d;
    end
end

reg z_reg;
always @(posedge clk) begin
    if (clk == 1'b1) begin
        if (clk == 1'b1) begin
            z_reg <= ~(q_xor & q_and | q_or);
        end
    end
end

assign z = z_reg;

