		if (rst) begin
			pos <= 3'b0;
			count <= 3'b0;
		end else begin
			temp = in;
			count = 3'b0;
			for (int i = 0; i < 8; i++) begin
				if (temp[i]) begin
					count = 3'd1;
				end else begin
					count = count + 1;
