				if (count == 3'd8) begin
					pos <= 3'd7;
				end else if (count == 3'd1) begin
					pos <= i;
				end
			end
		end
	end

	always_comb begin
		if (rst) begin
			pos = 3'b0;
		end
	end

	always @(*) begin
		if (rst) begin
			temp = 8'b0;
		end
	end

	always @(*) begin
		if (rst) begin
			count = 3'b0;
		end
	end

	parameter clk = 1;
	parameter rst = 1;
endmodule

