    localparam [2:0] STATE1 = 3'b001;
    localparam [2:0] STATE2 = 3'b010;
    localparam [2:0] STATE3 = 3'b011;
    localparam [2:0] STATE4 = 3'b100;

    // Define the next state and output values for each state
    reg [2:0] next_state;
    reg [2:0] next_Y;
    reg next_z;

    // Define the state machine state
    reg [2:0] current_state;

    // Define the state machine state machine
    always @ (posedge clk) begin
        if (reset) begin
            current_state <= IDLE;
            Y0 <= 1'b0;
            z <= 1'b0;
        end else begin
            case (current_state)
                IDLE: begin
                    next_state <= (x)? STATE3 : STATE1;
                    next_Y <= (x)? STATE3 : STATE1;
                    next_z <= 1'b0;
                end
                STATE1: begin
                    next_state <= (x)? STATE4 : STATE2;
                    next_Y <= (x)? STATE4 : STATE2;
                    next_z <= 1'b0;
                end
                STATE2: begin
                    next_state <= (x)? STATE1 : STATE2;
                    next_Y <= (x)? STATE1 : STATE2;
