    localparam IDLE = 3'd0;
    localparam COUNTING = 3'd4;
    localparam DONE = 3'd5;
    localparam RESET = 3'd6;
    localparam ZERO = 3'd0;
    localparam ONE = 3'd1;

    // Define the state machine
    reg [2:0] state = IDLE;
    reg [2:0] count = 3'b0;

    // Define the reset signal
    reg reset = 1'b0;

    always @(posedge clk) begin
        reset <= 1'b0;
        if (!reset) begin
            if (a) begin
                state <= COUNTING;
                count <= 3'b0;
            end
            else begin
                state <= IDLE;
                count <= 3'b0;
            end
        end
        else begin
            case (state)
                IDLE: begin
                    if (a) begin
                        state <= COUNTING;
                        count <= 3'b0;
                    end
                end
                COUNTING: begin
                    if (count == 3'd4) begin
                        state <= DONE;
                    end
                    else begin
                        count <= count + 1;
                    end
                end
                DONE: begin
                    if (a) begin
                        state <= RESET;
                    end
                    else begin
                        state <= IDLE;
                    end
                end
                RESET: begin
                    state <= IDLE;
                end
            endcase
        end
    end

    // Assign the output
