    assign ab01 = ~c & d;
    assign ab11 = ~c & ~d;
    assign ab10 = ~{c, d};

    // 4-to-1 multiplexer
    assign mux_in[0] = ab00 & ~ab01 & ~ab11 & ~ab10;
    assign mux_in[1] = ab00 & ab01 & ~ab11 & ~ab10;
    assign mux_in[2] = ab00 & ~ab01 & ab11 & ~ab10;
