    assign m0_out = {c, d};

    // 2-to-1 multiplexer for m0_out and 1
    assign m1_out = {~c, ~d};

    // 2-to-1 multiplexer for m0_out and m1_out
    assign m2_out = {m0_out[1], m1_out[1]};

    // 4-to-1 multiplexer
    assign mux_in = {m2_out[0], m2_out[1], m2_out[1], m2_out[0]};

