module top_module(
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    // Define the clock and reset signals
    reg clk_r = 0;
    reg reset = 1;

    // Define the game state
    reg [255:0] state = 0;

    // Define the clock and reset timing
    always @(posedge clk)
        if (reset)
            reset <= 0;
        else
            clk_r <= clk;

    // Define the game logic
    always @(posedge clk_r)
    begin
        if (load)
            state <= data;
        else
        begin
            // Create a copy of the current state
            reg [255:0] next_state = state;

            // Iterate over each cell in the grid
            for (int i = 0; i < 256; i = i + 1)
            begin
                // Calculate the row and column of the current cell
                int row = i / 16;
                int col = i % 16;

                // Calculate the number of alive neighbours
                int alive_neighbours = 0;
                for (int j = -1; j <= 1; j = j + 1)
                begin
                    for (int k = -1; k <= 1; k = k + 1)
                    begin
                        // Calculate the row and column of the neighbour
                        int neighbour_row = (row + j + 16) % 16;
                        int neighbour_col = (col + k + 16) % 16;

                        // Check if the neighbour is alive
                        if (state[(neighbour_row * 16 + neighbour_col) * 4 + 0] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 1] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 2] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 3] == 1)
                            alive_neighbours = alive_neighbours + 1;
                    end
                end

                // Update the cell state based on the number of alive neighbours
                case (alive_neighbours)
                    0: next_state[i] = 0;
                    1: next_state[i] = 0;
                    2: next_state[i] = state[i];
                    3: next_state[i] = 1;
                    default: next_state[i] = 0;
                endcase
            end

            // Update the game state
            state <= next_state;
        end
    end

    // Assign the game state to the output
    assign q = state;

endmodule

module top_module(
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    // Define the clock and reset signals
    reg clk_r = 0;
    reg load_r = 0;

    // Define the game state
    reg [255:0] q_r;

    // Define the number of rows and columns in the grid
    localparam ROWS = 16;
    localparam COLS = 16;

    // Define the number of neighbours for each cell
    localparam NEIGHBOURS = 8;

    // Define the game state at the previous time step
    reg [255:0] q_prev;

    // Define the game state at the next time step
    reg [255:0] q_next;

    // Define the number of neighbours for each cell
    reg [255:0] neighbours;

    // Define the number of alive neighbours for each cell
    reg [255:0] alive_neighbours;

    // Define the next state of each cell
    reg [255:0] next_state;

    // Define the clock and reset logic
    always @(posedge clk) begin
        clk_r <= clk;
        load_r <= load;
    end

    // Define the game state logic
    always @(posedge clk_r) begin
        if (load_r) begin
            q_r <= data;
        end else begin
            // Calculate the number of neighbours for each cell
            neighbours = 0;
            for (int i = 0; i < COLS; i = i + 1) begin
                for (int j = 0; j < ROWS; j = j + 1) begin
                    // Calculate the index of the current cell
                    int idx = (j * COLS + i);
                    // Calculate the number of neighbours for the current cell
                    neighbours[idx] = (q_r[idx - COLS - 1] + q_r[idx + COLS + 1] + q_r[idx - 1] + q_r[idx + 1] + q_r[idx - COLS] + q_r[idx + COLS] + q_r[idx - COLS - 1] + q_r[idx + COLS + 1]) & 1;
                end
            end

            // Calculate the next state of each cell
            alive_neighbours = 0;
            for (int i = 0; i < COLS; i = i + 1) begin
                for (int j = 0; j < ROWS; j = j + 1) begin
                    // Calculate the index of the current cell
                    int idx = (j * COLS + i);
                    // Calculate the number of alive neighbours for the current cell
                    alive_neighbours[idx] = neighbours[idx] & q_r[idx];
                end
            end

            // Calculate the next state of each cell
            next_state = 0;
            for (int i = 0; i < COLS; i = i + 1) begin
                for (int j = 0; j < ROWS; j = j + 1) begin
                    // Calculate the index of the current cell
                    int idx = (j * COLS + i);
                    // Calculate the next state of the current cell
                    case (alive_neighbours[idx])
                        0: next_state[idx] = 0;
                        1: next_state[idx] = q_r[idx];
                        2: next_state[idx] = q_r[idx];
                        3: next_state[idx] = 1;
                        default: next_state[idx] = 0;
                    endcase
                end
            end

            // Update the game state
            q_r <= next_state;
        end
    end

    // Assign the game state to the output
    assign q = q_r;

endmodule

