    input [31:0] in,
    output reg [31:0] out
);

    reg [31:0] prev_in = 0;
    reg [31:0] capture = 0;

    always @(posedge clk) begin
        if (reset) begin
            capture <= 0;
        end else begin
            for (int i = 0; i < 32; i++) begin
                if (prev_in[i] == 1 && in[i] == 0) begin
                    capture[i] <= 1;
                end else begin
                    capture[i] <= 0;
                end
            end
        end
    end

    always @(posedge clk) begin
        out <= capture;
    end

    always @(posedge clk) begin
        prev_in <= in;
    end

endmodule

module top_module (
	input [7:0] in,
	output reg [2:0] pos
);

	reg [7:0] temp;
	reg [2:0] count;

	always @(posedge clk) begin
		if (rst) begin
			pos <= 3'b0;
			count <= 3'b0;
		end else begin
			temp = in;
			count = 3'b0;
			for (int i = 0; i < 8; i++) begin
				if (temp[i]) begin
					count = 3'd1;
				end else begin
					count = count + 1;
				end
				if (count == 3'd8) begin
					pos <= 3'd7;
				end else if (count == 3'd1) begin
					pos <= i;
				end
			end
		end
	end

	always_comb begin
		if (rst) begin
			pos = 3'b0;
		end
	end

	always @(*) begin
		if (rst) begin
			temp = 8'b0;
		end
	end

	always @(*) begin
		if (rst) begin
			count = 3'b0;
		end
	end

	parameter clk = 1;
	parameter rst = 1;

endmodule

