module top_module (
	input clk,
	input resetn,
	input x,
	input y,
	output f,
	output g
);

reg [1:0] state;
reg [1:0] x_count;
reg [1:0] y_count;
reg f;
reg g;

always @(posedge clk or negedge resetn) begin
	if (!resetn) begin
		state <= 2'b00; // State A
		x_count <= 2'b00;
		y_count <= 2'b00;
		f <= 1'b0;
		g <= 1'b0;
	end else begin
		case (state)
			2'b00: // State A
				begin
					if (!resetn) begin
						state <= 2'b00;
						x_count <= 2'b00;
						y_count <= 2'b00;
						f <= 1'b0;
						g <= 1'b0;
					end else begin
						f <= 1'b1;
						state <= 2'b01; // Move to State B
						x_count <= 2'b00;
					end
				end
			2'b01: // State B
				begin
					if (x == 1'b1) begin
						x_count <= x_count + 1;
						if (x_count == 2'b11) begin
							state <= 2'b10; // Move to State C
							x_count <= 2'b00;
						end
					end else begin
						x_count <= 2'b00;
					end
				end
			2'b10: // State C
				begin
					if (y == 1'b1) begin
						y_count <= y_count + 1;
						if (y_count == 2'b11) begin
							g <= 1'b1;
						end
					end else begin
						y_count <= 2'b00;
					end
					if (y_count == 2'b00) begin
						g <= 1'b0;
					end
				end
		endcase
	end
end

endmodule

