reg [1:0] y_count;
reg f;
reg g;

always @(posedge clk or negedge resetn) begin
	if (!resetn) begin
		state <= 2'b00; // State A
		f <= 0;
		g <= 0;
		x_count <= 3'b000;
		y_count <= 2'b00;
	end else begin
		case (state)
			2'b00: // State A
				begin
					f <= 0;
					g <= 0;
					if (x == 1 && y == 1) begin
						state <= 2'b01; // Move to State B
					end
				end
			2'b01: // State B
				begin
					f <= 1;
					g <= 0;
					if (x == 1 && x_count < 3) begin
						x_count <= x_count + 1;
					end else if (y == 1 && y_count < 2) begin
						y_count <= y_count + 1;
					end else if (x_count == 3 || y_count == 2) begin
						state <= 2'b10; // Move to State C
					end
				end
			2'b10: // State C
				begin
					f <= 1;
					g <= (y_count == 2);
				end
		endcase
	end
end

endmodule

