module top_module(
    input clk,
    input areset, 

    input predict_valid,
    input [6:0] predict_pc,
    output reg predict_taken, 
    output reg [6:0] predict_history,

    input train_valid,
    input train_taken,
    input train_mispredicted,
    input [6:0] train_history, 
    input [6:0] train_pc
);

    parameter PHT_SIZE = 128;
    parameter HISTORY_BITS = 7;

    reg [HISTORY_BITS-1:0] global_branch_history;
    reg [HISTORY_BITS-1:0] pht [0:PHT_SIZE-1];
    reg [1:HISTORY_BITS-1] pht_state [0:PHT_SIZE-1];

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            global_branch_history <= 0;
            for (int i = 0; i < PHT_SIZE; i++) begin
                pht[i] <= 0;
                pht_state[i] <= 2'b00;
            end
        end else begin
            if (train_valid) begin
                int index;
                index = predict_pc ^ global_branch_history;
                pht[index] <= train_history;
                if (train_mispredicted) begin
                    global_branch_history <= train_history;
                end
            end

            if (predict_valid) begin
                int index;
                index = predict_pc ^ global_branch_history;
                predict_taken <= (pht_state[index] == 2'b11);
                predict_history <= pht[index];
                pht_state[index] <= (train_valid) ? 2'b01 : (predict_taken) ? 2'b10 : 2'b00;
            end
        end
    end

endmodule

module top_module(
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    // Define the clock and reset signals
    reg clk_r = 0;
    reg reset = 1;

    // Define the game state
    reg [255:0] state = 0;

    // Define the clock and reset timing
    always @(posedge clk)
        if (reset)
            reset <= 0;
        else
            clk_r <= clk;

    // Define the game logic
    always @(posedge clk_r)
    begin
        if (load)
            state <= data;
        else
        begin
            // Create a copy of the current state
            reg [255:0] next_state = state;

            // Iterate over each cell in the grid
            for (int i = 0; i < 256; i = i + 1)
            begin
                // Calculate the row and column of the current cell
                int row = i / 16;
                int col = i % 16;

                // Calculate the number of alive neighbours
                int alive_neighbours = 0;
                for (int j = -1; j <= 1; j = j + 1)
                begin
                    for (int k = -1; k <= 1; k = k + 1)
                    begin
                        // Calculate the row and column of the neighbour
                        int neighbour_row = (row + j + 16) % 16;
                        int neighbour_col = (col + k + 16) % 16;

                        // Check if the neighbour is alive
                        if (state[(neighbour_row * 16 + neighbour_col) * 4 + 0] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 1] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 2] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 3] == 1)
                            alive_neighbours = alive_neighbours + 1;
                    end
                end

                // Update the cell state based on the number of alive neighbours
                case (alive_neighbours)
                    0: next_state[i] = 0;
                    1: next_state[i] = 0;
                    2: next_state[i] = state[i];
                    3: next_state[i] = 1;
                    default: next_state[i] = 0;
                endcase
            end

            // Update the game state
            state <= next_state;
        end
    end

    // Assign the game state to the output
    assign q = state;

endmodule

