                int row = i / 16;
                int col = i % 16;

                // Calculate the number of alive neighbours
                int alive_neighbours = 0;
                for (int j = -1; j <= 1; j = j + 1)
                begin
                    for (int k = -1; k <= 1; k = k + 1)
                    begin
                        // Calculate the row and column of the neighbour
                        int neighbour_row = (row + j + 16) % 16;
                        int neighbour_col = (col + k + 16) % 16;

                        // Check if the neighbour is alive
                        if (state[(neighbour_row * 16 + neighbour_col) * 4 + 0] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 1] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 2] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 3] == 1)
                            alive_neighbours = alive_neighbours + 1;
                    end
                end

                // Update the cell state based on the number of alive neighbours
                case (alive_neighbours)
                    0: next_state[i] = 0;
                    1: next_state[i] = 0;
                    2: next_state[i] = state[i];
                    3: next_state[i] = 1;
                    default: next_state[i] = 0;
                endcase
            end

            // Update the game state
            state <= next_state;
        end
    end

    // Assign the game state to the output
    assign q = state;

endmodule

module top_module(
    input clk,
    input reset,
    input ena,
    output reg pm,
    output reg [7:0] hh,
    output reg [7:0] mm,
    output reg [7:0] ss);

    reg [3:0] bcd_ss;
    reg [3:0] bcd_mm;
    reg [3:0] bcd_hh;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pm <= 0;
            bcd_ss <= 8'd0;
            bcd_mm <= 8'd0;
            bcd_hh <= 8'd12;
        end else begin
            if (ena) begin
                bcd_ss <= bcd_ss + 1;
                if (bcd_ss == 8'd60) begin
                    bcd_ss <= 8'd0;
                    bcd_mm <= bcd_mm + 1;
                    if (bcd_mm == 8'd60) begin
                        bcd_mm <= 8'd0;
                        bcd_hh <= bcd_hh + 1;
                        if (bcd_hh == 8'd13) begin
                            bcd_hh <= 8'd1;
                        end
                    end
                end
            end
        end
    end

    always @(posedge clk) begin
        if (bcd_hh > 8'd12) begin
            pm <= 1;
            hh <= {4'b0, bcd_hh - 8'd12};
        end else begin
            pm <= 0;
            hh <= {4'b0, bcd_hh};
        end
        mm <= {4'b0, bcd_mm};
        ss <= {4'b0, bcd_ss};
    end

endmodule

module top_module(
    input clk,
    input reset,
    input ena,
    output reg pm,
    output reg [7:0] hh,
    output reg [7:0] mm,
    output reg [7:0] ss);

    // BCD counters for hours, minutes, and seconds
    reg [3:0] bcd_hh;
    reg [3:0] bcd_mm;
    reg [3:0] bcd_ss;

    // Clock domain for BCD counter updates
    always @(posedge clk) begin
        if (reset) begin
            // Reset BCD counters to initial values
            bcd_hh <= 8'd0;
            bcd_mm <= 8'd0;
            bcd_ss <= 8'd0;
            // Set PM indicator to AM
            pm <= 0;
        end else begin
            // Increment BCD counter for seconds
            bcd_ss <= bcd_ss + 1;

            // Handle overflow for seconds counter
            if (bcd_ss == 8'd60) begin
                bcd_ss <= 8'd0;
                bcd_mm <= bcd_mm + 1;
            end

            // Handle overflow for minutes counter
            if (bcd_mm == 8'd60) begin
                bcd_mm <= 8'd0;
                bcd_hh <= bcd_hh + 1;
            end

            // Handle overflow for hours counter
            if (bcd_hh == 8'd24) begin
                bcd_hh <= 8'd0;
            end
        end
    end

    // Convert BCD counters to human-readable time format
    always @(posedge clk) begin
        // Set PM indicator based on hours value
        if (bcd_hh > 8'd12) begin
            pm <= 1;
            hh <= {4'b0, bcd_hh - 8'd12};
        end else begin
            pm <= 0;
            hh <= {4'b0, bcd_hh};
        end

        // Convert BCD counters to BCD digits
        mm <= {4'b0, bcd_mm};
        ss <= {4'b0, bcd_ss};
    end

endmodule

module top_module(
    input clk,
    input reset,
    output reg [3:1] ena,
    output reg [15:0] q
);

    reg [3:0] ones, tens, hundreds, thousands;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ones <= 4'b0000;
            tens <= 4'b0000;
            hundreds <= 4'b0000;
            thousands <= 4'b0000;
            ena <= 4'b0000;
        end else begin
            // Increment the least significant digit first
            ones <= ones + 1;
            if (ones == 4'b1010) begin // 9 in binary
                ones <= 4'b0000;
                tens <= tens + 1;
            end

            if (tens == 4'b1010) begin // 9 in binary
                tens <= 4'b0000;
                hundreds <= hundreds + 1;
            end

            if (hundreds == 4'b1010) begin // 9 in binary
                hundreds <= 4'b0000;
                thousands <= thousands + 1;
            end

            // Set enable signals for upper three digits
            ena[0] <= (thousands != 4'b1010);
            ena[1] <= (thousands != 4'b1010 || hundreds != 4'b1010);
            ena[2] <= (thousands != 4'b1010 || hundreds != 4'b1010 || tens != 4'b1010);
        end
    end

    assign q = {thousands, hundreds, tens, ones};

endmodule

